NAME = 'FreGeneve1669: Le Nouveau Testament de la Bible de Genève de 1669'
BOOK = 'Mark'

CHAPTERS = {
    1: {
        1: "Le commencement de l'Evangile de Jefus Chrift Fils de Dieu.",
        2: "Ainfi qu'il eft écrit és Prophetes, Voici, j'envoye mon meffager devant ta face, qui preparera ta voye au devant de toi.",
        3: 'La voix de celui qui crie au defert eft, Preparez le chemin du Seigneur, dreffez fes fentiers.',
        4: 'Jean baptifoit au defert, & prefchoit le Baptefme de repentance, en remiffion des pechez.',
        5: 'Et tout le païs de Judée, & ceux de Jerufalem, alloyent vers lui, & eftoyent tous baptifez par lui au fleuve du Jordain, confeffans leurs pechez.',
        6: 'Or Jean eftoit veftu de poils de chameau, & avoit une ceinture de cuir autour de fes reins, & mangeoit des fauterelles & du miel fauvage.',
        7: 'Et prefchoit, difant, Celui qui eft plus fort que moi, vient apres moi, duquel je ne fuis pas digne en me baiffant de deflier la courroye des fouliers.',
        8: "Il eft vrai que je vous ai baptizez d'eau: mais il vous baptizera du faint Efprit.",
        9: 'Or il advint en ces jours-là que Jefus vint de Nazareth, ville de Galilée, & fut baptizé par Jean au Jordain.',
        10: "Et incontinent comme il fortoit hors de l'eau, il vid les cieux fe fendre, & le faint Efprit defcendre fur lui comme une colombe.",
        11: "Alors il fe fit une voix, venant des cieux, difant, Tu es mon fils bien-aimé, auquel j'ai pris mon bon-plaifir.",
        12: "Et incontinent l'efprit le pouffa au defert.",
        13: 'Et il fut là au defert quarante jours, eftant tenté de Satan: & eftoit avec les beftes fauvages, & les Anges le fervoyent.',
        14: "Or apres que Jean eût efté mis en prifon, Jefus vint en Galilée, prefchant l'Evangile du Royaume de Dieu:",
        15: "Et difant, Le temps eft accompli, & le royaume de Dieu eft approché: amendez-vous, & croyez à l'Evangile.",
        16: 'Or en cheminant auprés de la mer de Galilée, il vid Simon & André fon frere, jettans leurs filez en la mer, (car ils eftoyent pefcheurs.)',
        17: "Alors Jefus leur dit, Venez aprez moi, & je vous ferai eftre pefcheurs d'hommes.",
        18: 'Et auffi-toft laiffant leurs filez, ils le fuivirent.',
        19: 'Et de là paffant un peu plus outre, il vid Jaques fils de Zebedée & Jean fon frere, qui racouftroyent leurs filez en la neffelle.',
        20: 'Et incontinent il les appella, & eux laiffans leur pere Zebedée en la naffelle avec les ouvriers, le fuivirent.',
        21: 'Puis ils entrerent en Capernaum: & toft apres au jour du Sabbat, eftant entré en la Synagogue, il enfeignoit.',
        22: "Et ils s'eftonnoyent de fa doctrine: car il les enfeignoit comme ayant authorité, & non point comme les Scribes.",
        23: "Or il fe trouva en leur Synagogue un homme qui avoit un efprit immonde, lequel s'écria,",
        24: "Difant, Ha! qu'y a-t'il entre toi & nous, Jefus Nazarien? es-tu venu pour nous deftruire? je fçay qui tu es affavoir le faint de Dieu.",
        25: 'Mais Jefus le tança, difant, Tai-toi, & fors de lui.',
        26: "Alors l'efprit immonde le dérompant, & s'écriant à haute voix, fortit hors de lui.",
        27: "Et ils s'eftonnerent tous, tellement qu'ils s'enqueroyent entr'eux, difans, Qu'eft ceci, quelle doctrine nouvelle eft celle-ci? qu'il commande d'authorité, mefmes aux efprits immondes, & ils lui obeïssent?",
        28: "Ainfi fa renommée courut incontinent par toute la contrée d'alentour de la Galilée.",
        29: "Et toft apres eftans fortis de la Synagogue, ils vinrent avec Jaques & Jean en la maifon de Simon & d'André.",
        30: "Or la belle-mere de Simon gifoit malade de la fiévre: & auffi-toft ils lui parlerent d'elle.",
        31: "Alors s'approchant, il la leva, en la prenant par la main: & auffi-toft la fiévre la laiffa, & elle les fervit.",
        32: 'Le foir eftant venu, comme le foleil fe couchoit, ils lui apportoyent tous ceux qui fe portoyent mal, & les demoniaques.',
        33: 'Et toute la ville eftoit affemblée à la porte.',
        34: "Et il guerit tous ceux qui eftoyent malades de diverfes maladies: & jetta hors plufieurs diables, ne permettant point que les diables diffent qu'ils le connuffent.",
        35: "Puis au matin comme il eftoit encore fort nuit, s'étant levé il fortit, & s'en alla en un lieu defert, & prioit là.",
        36: 'Et Simon, & les autres qui eftoyent avec lui, le fuivirent.',
        37: "Et quand ils l'eurent trouvé, ils lui dirent, Tous te cherchent.",
        38: "Alors il leur dit, Allons-nous-en aux prochaines bourgades, afin que j'y prefche auffi: car je fuis venu pour cela.",
        39: 'Il prefchoit donc en leurs Synagogues, par toute la Galilée, & jettoit hors les diables.',
        40: "Et un lepreux vint à lui, le priant, & s'agenoüillant devant lui, & difant, Si tu veux, tu peux me nettoyer.",
        41: 'Alors Jefus eftant émeu de compaffion, eftendit fa main, & le toucha, & lui dit, Je le veux, fois nettoyé.',
        42: "Et quand il l 'eût dit, la lepre partit auffi-toft de lui, & il fut nettoyé.",
        43: "Et l'ayant menacé, il le renvoya incontinent,",
        44: "Et lui dit, Garde-toi d'en rien dire à perfonne: mais va-t'en, & te montre au Sacrificateur, & prefente pour ta purification les chofes que Moyfe a commandées, pour leur eftre en témoignage.",
        45: "Mais lui eftant parti commença à publier plufieurs chofes, & à divulguer l'affaire: tellement que Jefus ne pouvoit entrer à découvert en la ville, mais il fe tenoit en des lieux deferts, & de toutes parts on venoit à lui.",
    },
    2: {
        1: "Quelques jours apres il entra derechef en Capernaum: & on ouït dire qu'il eftoit en la maifon.",
        2: "Et auffi-toft plufieurs s'y affemblerent, tellement que mefmes l'endroit d'auprés de la porte ne les pouvoit contenir, & il leur annonçoit la parole.",
        3: 'Alors quelques-uns vinrent à lui, apportans un paralytique, qui eftoit porté par quatre.',
        4: "Mais parce qu'ils ne pouvoyent approcher de lui à caufe de la foule, ils découvrirent le toit du lieu où eftoit Jefus: & l'ayant percé, devalerent le petit lit auquel le paralytique gifoit.",
        5: 'Alors Jefus ayant veu leur foi, dit au paralytique, Mon fils, tes pechez te font pardonnez.',
        6: 'Or quelques-uns des Scribes eftoyent là affis, & difputoyent en leurs coeurs, difans,',
        7: "Pourquoi celui-ci prononce-t'il ainfi des blafphemes? Qui eft-ce qui peut pardonner les pechez, finon un feul Dieu?",
        8: "Et incontinent Jefus ayant connu en fon efprit, qu'ils difputoyent ainfi en eux-mefmes, leur dit, Pourquoi difputez-vous de telles chofes en vos coeurs?",
        9: 'Lequel eft le plus aifé, ou de dire au paralytique, Tes pechez te font pardonnez: ou de dire, Leve-toi, & charge ton petit lit, & chemine?',
        10: "Or afin que vous fçachiez que le Fils de l'homme a pouvoir de pardonner les pechez en la terre (il dit au paralytique.)",
        11: "Je te dis, Leve-toi & charge ton petit lit, & t'en va en ta maifon.",
        12: "Et lui fe leva auffi-toft, & ayant chargé fon petit lit, il fortit en la prefence de tous: tellement qu'ils furent tous eftonnez, & glorifioyent Dieu, difans, Nous ne vifmes jamais une telle chofe.",
        13: "Alors il s'en alla derechef vers la mer, & tout le peuple venoit à lui, & il les enfeignoit.",
        14: "Et en paffant, il vid Levi fils d'Alphée, affis au lieu du peage, & lui dit, Sui moi: & lui s'eftant levé le fuivit",
        15: "Et il advint comme Jefus eftoit à table en la maifon d'icelui, que plufieurs peagers & gens de mauvaife vie, fe mirent auffi à table avec Jefus & fes difciples: car il y en avoit beaucoup qui pareillement l'avoyent fuivi.",
        16: "Dont les Scribes & les Pharifiens, voyans qu'il mangeoit avec les peagers & gens de mauvaife vie, difoyent à fes difciples, Pourquoi eft-ce qu'il mange & qu'il boit avec les peagers & les mal-vivans?",
        17: "Et Jefus ayant entendu cela, leur dit, Ceux qui font en fanté n'ont pas befoin de medecin: mais ceux qui fe portent mal. Je ne fuis point venu appeller les juftes, mais les pecheurs à repentance.",
        18: 'Or les difciples de Jean & des Pharifiens jeufnoyent: lefquels vinrent vers lui, & lui dirent, Pourquoi les difciples de Jean & des Pharifiens jeufnent-ils: mais tes difciples ne jeufnent point?',
        19: "Et Jefus leur refpon dit, Les gens de nopces peuvent-ils jeufner pendant que le nouveau marié eft avec eux? Durant le temps qu'ils ont le nouveau marié avec eux, ils ne peuvent jeufner.",
        20: 'Mais les jours viendront que le nouveau marié leur fera ofté, & alors ils jeufneront en ces jours-là.',
        21: 'Auffi nul ne coud une piece de drap neuf à un vieux veftement: autrement la piece du drap neuf, qui a efté mife pour remplage, emporte la pièce du vieux drap: & la rupture en eft pire.',
        22: "Pareillement nul ne met le vin nouveau en de vieux vaiffeaux: autrement le vin nouveau rompt les vaiffeaux, & le vin s'épand, & les vaiffeaux fe perdent: mais le vin nouveau doit eftre mis en des vaiffeaux neufs.",
        23: 'Et il advint comme il paffoit, en un jour de Sabbat, par des blés, que fes difciples en cheminant fe prirent à arracher des épics.',
        24: "Alors les Pharifiens lui dirent, Regarde, pourquoi font-ils ce qui n'eft pas permis aux Sabbats?",
        25: "Mais il leur dit, Ne leuftes-vous jamais ce que fit David quand il eut neceffité, & qu'il eut faim, lui & ceux qui eftoyent avec lui?",
        26: "Comme il entra en la maifon de Dieu, au temps d'Abiathar principal Sacrificateur, & mangea les pains de propofition, qu'il n'eftoit permis de manger finon aux Sacrificateurs: & en donna auffi à ceux qui eftoyent avec lui.",
        27: "Puis il leur dit, Le Sabbat eft fait pour l'homme, & non point l'homme, pour le Sabbat:",
        28: "Ainfi le Fils de l'homme eft Seigneur auffi du Sabbat.",
    },
    3: {
        1: 'Puis il entra derechef en la Synagogue: & il y avoit là un homme qui avoit la main feche.',
        2: "Et ils l'obfervoyent, pour voir, s'il le gueriroit au Sabbat, afin de l'accufer.",
        3: "Alors il dit à l'homme qui avoit la main feche, Leve-toi en place.",
        4: 'Puis il leur dit, Eft-il permis de bien faire és Sabbats, ou de mal faire? de fauver une perfonne, ou de la tuër? Mais ils fe teurent.',
        5: "Alors en les regardant à l'entour avec indignation, & pareillement marri de l'endurciffement de leur coeur, il dit au perfonnage, Eften ta main. Et il l'eftendit: & fa main fut renduë faine comme l'autre.",
        6: 'Alors les Pharifiens eftans fortis, confulterent avec les Herodiens contre lui, comment ils le feroyent perir.',
        7: "Mais Jefus avec fes difciples fe retira vers la mer, & une grande multitude le fuivit de Galilée, & de Judée, & de Jerufalem, & d'Idumée, & de par delà le Jordain.",
        8: "Et ceux qui habitoyent à l'entour de Tyr & de Sidon, ayans entendu les grandes chofes qu'il faifoit, vinrent vers lui en grande multitude.",
        9: "Et il dit à fes difciples, qu'une petite naffelle ne bougeaft de là pour le fervir, à caufe des troupes, afin qu'elles ne l'empreffaffent point.",
        10: "Car il en avoit gueri beaucoup, tellement que tous ceux qui eftoyent affligez, fe jettoyent contre lui, afin qu'ils le touchaffent.",
        11: "Et les efprits immondes, quand ils le voioyent, fe profternoyent devant lui, & s'écrioyent, difans, Tu es le Fils de Dieu.",
        12: "Mais il les tançoit fort, afin qu'ils ne le fiffent point connoiftre.",
        13: "Puis il monta en une montagne, & appella ceux qu'il voulut, & ils vinrent à lui.",
        14: 'Et il en ordonna douze pour eftre avec lui, & pour les envoyer prefcher:',
        15: 'Et avoir puiffance de guerir les maladies, & de jetter hors les diables:',
        16: 'Affavoir Simon, lequel il furnomma Pierre.',
        17: "Puis Jaques fils de Zebedée, & Jean frere de Jaques, aufquels il impofa le nom de Boanerges, (qui vaut autant à dire qu'enfans de tonnerre)",
        18: "Et André, & Philippe, & Barthelemi, & Matthieu, & Thomas, & Jaques fils d'Alphée, & Thadée, & Simon le Cananéen,",
        19: 'Et Judas Ifcariot, qui auffi le trahit.',
        20: "Puis ils vinrent en la maifon: & derechef une multitude s'affembla, tellement qu'ils ne pouvoyent pas mefmes prendre leur repas.",
        21: "Et quand ceux qui lui attouchoyent eurent entendu cela, ils fortirent pour le faifir: car ils difoyent, qu'il eftoit hors du fens.",
        22: 'Et les Scribes, qui eftoyent defcendus de Jerufalem, difoyent, Il a Beelzebul, & jette hors les diables par le prince des diables.',
        23: 'Mais lui les ayant appellez, leur dit par fimilitudes, Comment peut Satan jetter Satan dehors?',
        24: 'Car fi un royaume eft divifé contre foi-mefme, ce royaume-là ne peut fubfifter.',
        25: 'Et fi une maifon eft divisée contre foi-mefme, cette maifon-là ne peut fubfifter.',
        26: "Pareillement fi Satan s'éleve contre foi-mefme, & eft divifé, il ne peut fubfifter, mais il s'en va faillir.",
        27: "Nul ne peut entrer en la maifon d'un homme fort, & piller fon bien, fi premierement il n'a lié l'homme fort: & alors il pillera fa maifon.",
        28: 'En verité je vous dis que toutes fortes de pechez feront pardonnez aux enfans des hommes, & toutes fortes de blafphemes par lefquels ils auront blafphemé.',
        29: "Mais quiconque aura blafphemé contre le faint Efprit, n'aura point de pardon eternellement, ains il fera coupable de condamnation eternelle.",
        30: "C'eft parce qu'ils difoyent, Il a l'efprit immonde.",
        31: "Ses freres donc & fa mere vinrent: & eftans dehors envoyerent quelques-uns vers lui pour l'appeller: & la multitude eftoit affife à l'entour de lui.",
        32: 'Ainfi donc on lui dit, Voila ta mere & tes freres là dehors, qui te demandent.',
        33: 'Mais il leur refpondit, difant, Qui eft ma mere, ou qui font mes freres?',
        34: "Et en regardant de tous coftez à l'environ, ceux qui eftoyent affis à l'entour de lui, il dit, Voici ma mere & mes freres.",
        35: 'Car quiconque fera la volonté de Dieu, celui-là eft mon frere, & ma foeur, & ma mere.',
    },
    4: {
        1: "Puis il fe prit derechef à enfeigner aupres de la mer: & de grandes troupes s'affemblerent vers lui: tellement qu'eftant monté en une naffelle, il fe tenoit affis en la naffelle fur la mer, & tout le peuple eftoit fur terre aupres de la mer.",
        2: 'Et il leur enfeignoit beaucoup de chofes par fimilitudes, & leur difoit en fa doctrine,',
        3: "Efcoutez; Voici, un femeur s'en alla pour femer.",
        4: "Et il advint qu'en femant, une partie de la femence cheut auprés du chemin, & les oifeaux du ciel vinrent, & la mangerent toute.",
        5: "L'autre partie cheut en des lieux pierreux, où elle n'avoit gueres de terre: & auffi-toft elle fe leva, parce qu'elle n'entroit pas profondement en terre:",
        6: "Mais quand le foleil fut levé, elle fut havie: & parce qu'elle n'avoit nulle racine, elle fe fecha.",
        7: "L'autre partie cheut entre les épines: & les épines monterent, & l'eftoufferent, & elle ne rendit point de fruit.",
        8: "Et l'autre partie cheut en bonne terre, & rendit du fruit, montant & croiffant: tellement qu'un grain en apporta trente, & l'autre foixante, & l'autre cent.",
        9: "Alors il leur dit, Qui a des oreilles pour ouïr, qu'il oye.",
        10: "Et quand il fut à part, ceux qui eftoyent autour de lui avec les douze, l'interrogerent touchant la fimilitude.",
        11: 'Et il leur dit, Il vous eft donné de connoiftre le fecret du royaume de Dieu: mais à ceux qui font dehors, toutes chofes fe traittent en fimilitudes:',
        12: "Afin qu'en voyant ils voyent, & n'apperçoivent point: & qu'en oyant ils oyent, & n'entendent point: de peur qu'ils fe convertiffent, & que les pechez leur foyent pardonnez.",
        13: 'Puis il leur dit, Ne fçavez-vous pas cette fimilitude? & comment connoiftrez-vous toutes les fimilitudes?',
        14: "Le femeur c' eft celui qui feme la parole.",
        15: "Et voici, ceux qui reçoivent la femence auprés du chemin, ce font ceux où la parole eft femée: mais apres qu'ils l'ont ouïe, incontinent Satan vient, & ofte la parole femée en leurs coeurs.",
        16: 'Et voici femblablement, ceux qui reçoivent la femence en des lieux pierreux, ce font ceux qui ayans ouï la parole, auffi-toft la reçoivent avec joye:',
        17: "Mais ils n'ont point de racine en eux-mefmes, & ne font qu'à temps: tellement qu'oppreffion ou perfecution advenant pour la parole, ils font incontinent fcandalifez.",
        18: 'Auffi ceux qui reçoivent la femence entre les épines, ce font ceux qui oyent la parole:',
        19: 'Mais les folicitudes de ce monde, & la fallace des richeffes, & les convoitifes des autres chofes, eftant entrées en leurs efprits, eftouffent la parole, & elle devient infructueufe.',
        20: "Mais voici, ceux qui ont receu la femence en bonne terre, ce font ceux qui oyent la parole & la reçoivent, & portent du fruit: l'un trente, & l'autre foixante, & l'autre cent.",
        21: "Il leur difoit auffi, La chandelle eft-elle apportée afin qu'elle foit mife fous un boiffeau, ou fous un lit? N'eft-ce point afin qu'elle foit mife fur un chandelier?",
        22: "Car il n'y a rien de fecret, qui ne foit enfin manifefté: & il n'y a rien de caché, qui ne vienne en evidence.",
        23: "Si quelqu'un a des oreilles pour ouïr, qu'il oye.",
        24: 'Davantage il leur dit, Regardez ce que vous oyez: de telle mefure que vous mefurerez, il vous fera mefuré: & à vous qui oyez, il fera adjoufté.',
        25: "Car à celui qui a, il lui fera donné: & à celui qui n'a rien, cela mefme qu'il a, lui fera ofté.",
        26: 'Davantage il dit, Le royaume de Dieu eft comme fi un homme ayant jetté la femence en la terre, dormoit & fe levoit de nuit & de jour:',
        27: 'Et que la femence germaft & creuft, lui ne fçachant comment.',
        28: "Car la terre d'elle-mefme produit premierement l'herbe, puis apres les épics, puis le plein froment en épic:",
        29: "Et quand le fruit s'eft montré, incontinent on y met la faucille, à caufe que la moiffon eft prefte.",
        30: 'Puis il difoit, A quoi accomparerons-nous le royaume de Dieu, ou de quelle fimilitude le reprefenterons-nous?',
        31: 'Il en prend comme du grain de femence de mouftarde, lequel eftant femé en terre, eft bien la plus petite de toutes les femences qui font jettées en la terre.',
        32: 'Mais apres eftre femé, il fe leve, & devient plus grand que toutes les autres herbes: & jette de grandes branches, tellement que les oifeaux du ciel peuvent baftir leurs logettes fous fon ombre.',
        33: "Ainfi par plufieurs telles fimilitudes, il leur traittoit de la parole felon qu'ils pouvoyent ouïr.",
        34: 'Et il ne parloit point à eux fans fimilitude: mais à part il declaroit le tout à fes difciples.',
        35: "Ce jour-là, quand le foir fut venu, il leur dit, Paffons de-là l'eau.",
        36: "Et apres avoir laiffé les troupes, ils le prirent avec eux ainfi qu'il eftoit en la naffelle. Or il y avoit auffi d'autres petites naffelles avec lui.",
        37: "Alors un grand tourbillon de vent fe leva, tellement que les vagues fe jettoyent en la naffelle, de forte qu'elle s'empliffoit déja.",
        38: "Or il eftoit en la pouppe, dormant fur un oreiller: alors ils l'éveillerent, & lui dirent, Maiftre, ne te foucies-tu point de ce que nous periffons?",
        39: "Mais lui s'eftant levé tança le vent, & dit à la mer, Tai-toi, tien-toi coye. Alors le vent ceffa, & il fe fit un grand calme.",
        40: "Puis il leur dit, Pourquoi eftes-vous ainfi craintifs? Comment, n'avez-vous point de foi?",
        41: "Mais ils craignirent de grande crainte, & difoyent l'un à l'autre, Mais qui eft celui-ci, que le vent mefmes & la mer lui obeïffent?",
    },
    5: {
        1: 'Et ils arriverent de-là la mer, en la contrée des Gadareniens.',
        2: 'Et quand il fut forti de la naffelle, incontinent un homme qui avoit un efprit immonde fortit des fepulcres, & le vint rencontrer.',
        3: 'Lequel avoit fa demeure és fepulcres, & nul ne le pouvoit tenir lié, non pas mefmes de chaines:',
        4: 'Parce que fouvent quand il avoit efté lié de ceps & de chaines, il avoit rompu les chaines, & mis les ceps en pieces: & perfonne ne le pouvoit dompter.',
        5: 'Et il eftoit continuellement de nuit & de jour és montagnes & és fepulcres, criant & fe frapant de pierres.',
        6: 'Quand donc de fort loin il vid Jefus, il accourut, & fe profterna devant lui:',
        7: "Et criant à haute voix, il dit, Qu'y a-t'il entre toi & moi, Jefus Fils du Dieu fouverain? je t'adjure de par Dieu que tu ne me tourmentes point.",
        8: '(Car Jefus lui difoit, Sors de cet homme, efprit immonde.)',
        9: "Alors il l'interrogea, Comment as-tu nom? Et il refpondit, difant, J'ai nom Legion: car nous fommes plufieurs.",
        10: "Et il le prioit fort qu'il ne les envoyaft point hors de cette contrée-là.",
        11: 'Or il y avoit là vers les montagnes un grand troupeau de pourceaux qui paiffoit.',
        12: 'Et tous ces diables-là le prioyent, difans, Envoye nous és pourceaux, afin que nous entrions dans eux. Et Jefus incontinent le leur permit.',
        13: 'Alors ces efprits immondes eftans fortis, entrerent és pourceaux: & le troupeau fe jetta du haut en bas en la mer: (or il y en avoit environ deux mille) & ils furent eftouffez en la mer.',
        14: "Et ceux qui paiffoyent les pourceaux s'enfuïrent, & en porterent les nouvelles en la ville, & par les villages.",
        15: 'Alors ils fortirent pour voir ce qui eftoit advenu, & vinrent à Jefus, & virent celui qui avoit efté demoniaque, affis & veftu, & de bon fens: voire celui qui avoit eu la legion: & ils eurent peur.',
        16: 'Et ceux qui avoyent veu cela, leur raconterent ce qui eftoit arrivé à ce demoniaque, & touchant les pourceaux.',
        17: "Alors ils fe prirent à le prier qu'il s'en allaft de leurs quartiers.",
        18: "Et quand il fut entré en la naffelle, celui qui avoit efté demoniaque le prioit qu'il fuft avec lui.",
        19: "Mais Jefus ne le lui permit point, mais lui dit, Va t'en en ta maifon vers les tiens, & leur raconte combien grandes chofes le Seigneur t'a faites, & comme il a eu pitié de toi.",
        20: "Il s'en alla donc, & fe mit à publier en Decapolis combien grandes chofes Jefus lui avoit faites: & tous s'en eftonnoyent.",
        21: "Et quand Jefus fut derechef paffé à l'autre rivage en une naffelle, de grandes troupes s'affemblerent vers lui; & il eftoit prés de la mer.",
        22: "Alors voici, l'un des principaux de la Synagogue, nommé Jaïrus, vint: & l'ayant veu, fe jetta à fes pieds:",
        23: "Et le prioit fort, difant, Ma petite fille eft à l'extremité, je te prie de venir, & de lui impofer les mains, afin qu'elle foit guerie, & qu'elle vive.",
        24: "Jefus donc s'en alla avec lui: & de grandes troupes le fuivoyent, tellement qu'elles l'empreffoyent.",
        25: "Or il y avoit une certaine femme travaillée d'une perte de fang depuis douze ans:",
        26: "Laquelle avoit beaucoup fouffert entre les mains de plufieurs medecins, & avoit defpenfé tout fon bien, & n'avoit rien profité: mais pluftoft elle eftoit allée en empirant.",
        27: 'Elle ayant ouï parler de Jefus, vint en la foule par derriere, & toucha fon habillement.',
        28: 'Car elle difoit, Si feulement je touche fes habillemens, je ferai guerie.',
        29: "Et incontinent le flux de fon fang s'eftancha, & elle fentit en fon corps, qu'elle eftoit guerie de fon fleau.",
        30: 'Et auffi-toft Jefus reconnoiffant en foi-mefme la vertu qui eftoit fortie de lui, fe retourna vers la foule, difant, Qui a touché mes habillemens?',
        31: "Et fes difciples lui dirent, Tu vois que la foule t'empreffe, & tu dis, Qui m'a touché?",
        32: "Mais il regardoit tout à l'entour, pour voir celle qui avoit fait cela.",
        33: 'Alors la femme craignant & tremblant, fçachant ce qui avoit efté fait en fa perfonne, vint & fe jetta devant lui, & lui dit toute la verité.',
        34: "Et il lui dit, Ma fille, ta foi t'a fauvée: va t'en en paix, & fois guerie de ton fleau.",
        35: 'Comme il parloit encore, quelques-uns arriverent de chez le principal de la Synagogue, difans, Ta fille eft morte: pourquoi travailles-tu le maiftre davantage?',
        36: "Et incontinent que Jefus eût oüi ce qu'on difoit, il dit au principal de la Synagogue, Ne crain point: croi feulement.",
        37: "Et il ne permit point qu'aucun le fuivift, finon Pierre, & Jaques, & Jean frere de Jaques.",
        38: 'Puis il vint en la maifon du principal de la Synagogue, & apperçeut le trouble, & ceux qui pleuroyent & jettoyent de grands cris.',
        39: "Et alors eftant entré dedans, il leur dit, Pourquoi eft-ce que vous vous troublez, & que vous pleurez? La petite fille n'eft pas morte, mais elle dort.",
        40: 'Et ils fe rioyent de lui: mais les ayant fait fortir, il prit le pere & la mere de la petite fille, & ceux qui eftoyent avec lui, & entra là où la petite fille eftoit gifante.',
        41: "Et ayant pris la main de l'enfant, il lui dit, Talitha cumi, qui vaut autant à dire, eftant expofé, que, Petite fille (je te dis) leve toi.",
        42: "Et incontinent la petite fille fe leva, & cheminoit: car elle eftoit âgée de douze ans. Dont ils furent eftonnez d'un grand eftonnement.",
        43: "Et il leur commanda fort que perfonne ne le fçeuft: & puis il dit qu'on lui donnaft à manger.",
    },
    6: {
        1: 'Apres il partit de là, & vint en fon païs: & fes difciples le fuivoyent.',
        2: "Et quand le Sabbat fut venu, il fe prit à enfeigner en la Synagogue: & beaucoup de ceux qui l'oioyent, s'eftonnoyent, difans, D'où viennent ces chofes à celui-ci? & quelle eft cette fageffe qui lui eft donnée, que mefmes de telles vertus fe font par fes mains?",
        3: "Celui-ci n'eft-il pas charpentier? fils de Marie, frere de Jaques, & de Jofes, & de Jude, & de Simon? fes foeurs auffi ne font-elles pas parmi nous? Et ils eftoyent fcandalifez en lui.",
        4: "Alors Jefus leur dit, Un Prophete n'eft point fans honneur, finon en fon païs, & entre fes parens & ceux de fa famille.",
        5: "Et il ne peut faire là aucune vertu, finon qu'il guerit quelque peu de malades, leur ayant impofé les mains.",
        6: "Et il s'eftonnoit de leur incredulité: & tournoyoit à l'entour des bourgades, enfeignant.",
        7: 'Alors il appella les douze, & commença de les envoyer deux à deux, & leur donna puiffance fur les efprits immondes.',
        8: 'Et leur commanda de ne rien prendre pour porter fur le chemin, finon un bafton feulement, ni mallete, ni pain, ni monnoye en leur ceinture.',
        9: "Mais qu'ils fuffent chauffez de fouliers, & qu'ils ne fe veftiffent point de deux robbes.",
        10: 'Il leur difoit auffi, En quelque part que vous entrerez en une maifon, demeurez-y jufques à ce que vous partiez de là.',
        11: 'Et tous ceux qui ne vous recevront point, & ne vous orront point, en partant de là fecoüez la poudre de deffous vos pieds, en témoignage contre eux: En verité je vous dis, que ceux de Sodome & de Gomorrhe feront plus tolerablement traittez au jour du jugement, que cette ville-là.',
        12: "Eux donc eftans partis, prefcherent qu'on s'amendaft.",
        13: "Et jetterent hors plufieurs diables, & oignirent d'huile plufieurs malades, & les guerirent.",
        14: "Or le roi Herode en ouït parler, (car le nom d'icelui eftoit fort celebre) & dit, Ce Jean qui baptizoit, eft reffufcité des morts, & pourtant les vertus montrent leur force en lui.",
        15: "Les autres difoyent, C'eft Elie: & les autres difoyent, C'eft un Prophete, ou comme l'un des Prophetes.",
        16: "Quand donc Herode eût entendu cela, il dit, Celui-ci eft ce Jean que j'ai decapité: il eft reffufcité des morts.",
        17: "Car Herode ayant envoyé fes gens avoit fait prendre Jean, & l'avoit lié en prifon, à caufe d'Herodias femme de Philippe fon frere, parce qu'il l'avoit prife en mariage.",
        18: "Car Jean difoit à Herode, Il ne t'eft pas permis d'avoir celle qui eft femme de ton frere.",
        19: 'Et pourtant Herodias lui en vouloit, & defiroit de le faire mourir: mais elle ne pouvoit.',
        20: "Car Herode craignoit Jean, fçachant qu'il eftoit homme jufte & faint, & l'avoit en reverence: & l'ayant ouï, faifoit beaucoup de chofes pour l'amour de lui, & l'écoutoit volontiers.",
        21: "Mais un jour eftant venu à propos, qu'Herode faifoit le feftin du jour de fa naiffance aux grands feigneurs, & aux capitaines, & aux principaux de Galilée:",
        22: "Et la fille d'Herodias eftant entrée, & ayant danfé, & ayant pleu à Herode, & auffi à ceux qui eftoyent enfemble à table: le roi dit à la jeune fille, Demande-moi ce que tu voudras, & je te le donnerai.",
        23: 'Et il lui jura, difant, Tout ce que tu me demanderas, je te le donnerai, voire jufques à la moitié de mon royaume.',
        24: "Elle donc eftant fortie, dit à fa mere, Qu'eft-ce que je demanderai? Et elle dit, La tefte de Jean Baptifte.",
        25: 'Et incontinent eftant rentrée avec grande affection vers le roi, elle lui fit fa requefte, difant, Je voudrois que tout à cette heure tu me donnaffes en un plat la tefte de Jean Baptifte.',
        26: "Et le roi eftant tres-marri, ne voulut pas toutefois l'éconduire, à caufe du ferment, & de ceux qui eftoyent à table avec lui.",
        27: "Mais il envoya incontinent l'un de fes gardes, & commanda qu'il apportaft la tefte d'icelui: lequel s'y en alla, & le decapita en la prifon.",
        28: "Et apporta la tefte d'icelui en un plat, & la donna à la jeune fille, & la jeune fille la donna à fa mere.",
        29: "Et fes difciples l 'ayant ouï, vinrent & emporterent fon corps, & le mirent en un fepulcre.",
        30: "Et les Apoftres fe raffemblerent vers Jefus, & lui raconterent tout ce qu'ils avoyent fait & enfeigné.",
        31: "Et il leur dit, Venez-vous-en à part en un lieu retiré, & vous repofez un petit: car il y avoit beaucoup d'allans & de venans, tellement qu'ils n'avoyent pas mefme le loifir de manger.",
        32: "Ils s'en allerent donc en une naffelle en un lieu retiré à part.",
        33: "Mais le peuple vid qu'ils s'en alloyent, & plufieurs le reconnurent, & y accoururent à pied de toutes les villes, & y vinrent devant eux, & s'affemblerent vers lui.",
        34: "Alors Jefus eftant forti, vid là de grandes troupes, & fut efmeu de compaffion envers elles, de ce qu'elles eftoyent comme des brebis qui n'avoyent point de pafteur: & fe mit à leur enfeigner plufieurs chofes.",
        35: 'Et comme il eftoit déja tard, fes difciples vinrent à lui, difans, Ce lieu eft defert, & il eft déja tard.',
        36: "Donne-leur congé, afin qu'ils s'en aillent aux villages & aux bourgades d'alentour, & qu'ils achetent des pains pour eux: car ils n'ont rien à manger.",
        37: 'Et refondant, il leur dit, Mais vous, donnez-leur à manger. Ils lui dirent, Irions-nous acheter des pains pour deux cens deniers, pour leur donner à manger?',
        38: "Et il leur dit, Combien avez-vous de pains? allez & regardez. Et apres l'avoir fçeu, ils dirent, Cinq, & deux poiffons.",
        39: "Alors il leur commanda qu'ils les fiffent tous affeoir par tablées fur l'herbe verte.",
        40: "Et ils s'affirent par rangées, par centaines & par cinquantaines.",
        41: "Et quand il eût pris les cinqs pains & les deux poiffons, en regardant vers le ciel, il rendit graces, & rompit les pains, & les bailla à fes difciples, afin qu'ils les miffent devant eux: & partagea les deux poiffons à tous.",
        42: 'Et tous en mangerent, & furent raffafiez.',
        43: 'Et ils recüeillirent des pieces de pain douze corbeilles pleines, & quelque refte de poiffons.',
        44: 'Or ceux qui en avoyent mangé eftoyent environ cinq mille hommes.',
        45: "Incontinent apres cela il contraignit fes difciples de monter en la naffelle, & d'aller devant lui, outre la mer vers Bethfaïda, pendant qu'il donneroit congé aux troupes.",
        46: "Et quand il leur eût donné congé, il s'en alla en la montagne pour prier.",
        47: 'Le foir eftant venu, la naffelle eftoit au milieu de la mer, & il eftoit lui feul fur la terre.',
        48: "Et il vid qu'ils avoyent grand'peine à tirer, car le vent leur eftoit contraire: & environ la quatriéme veille de la nuit, il vint vers eux cheminant fur la mer, & les vouloit paffer.",
        49: "Mais quand ils le virent cheminant fur la mer, ils penferent que ce fuft un fantofme: dont ils s'écrierent.",
        50: "Car ils le voyoyent tous, & furent troublez: mais incontinent il parla à eux, & leur dit, Affeurez-vous, c'eft moi: n'ayez point de peur.",
        51: "Alors il monta en la naffelle vers eux, & le vent ceffa: dont ils s'eftonnerent beaucoup plus fort en eux-mefmes, & s'émerveillerent.",
        52: "Car ils n'avoyent pas bien pris garde au fait des pains: d'autant que leur coeur eftoit ftupide.",
        53: 'Et quand ils furent paffez outre, ils vinrent en la contrée de Genezareth, & arriverent au port.',
        54: 'Et comme ils furent fortis de la naffelle, ceux du lieu le reconnurent incontinent:',
        55: "Et coururent ça & là par toute la contrée d'alentour, & fe prirent à lui apporter ça & là en de petits lits ceux qui fe portoyent mal, là où ils oyoyent dire qu'il eftoit.",
        56: 'Et par tout où il eftoit entré és bourgades, ou és villes, ou és villages, ils mettoyent les malades és marchez: & le prioyent que pour le moins ils puffent toucher le bord de fa robe: & tous ceux qui le touchoyent eftoyent gueris.',
    },
    7: {
        1: "Alors les Pharifiens, & quelques-uns des Scribes qui eftoyent venus de Jerufalem, s'affemblerent vers lui.",
        2: "Et voyans quelques-uns de fes difciples prendre leur repas avec les mains communes, (c'eft à dire, fans eftre lavées) ils les en blamoyent.",
        3: "(Car les Pharifiens & tous les Juifs ne mangent point qu'ils ne lavent fouvent leurs mains, retenans la tradition des anciens:",
        4: "Et retournans du marché, ils ne mangent point, qu'ils ne foyent lavez. Il y a auffi beaucoup d'autres chofes qu'ils ont prifes à garder, comme les lavemens des coupes, des brocs, de la vaiffelle, & des chalits.)",
        5: "Là deffus les Pharifiens & les Scribes l'interrogerent, difans, Pourquoi tes difciples ne cheminent-ils point felon la tradition des anciens: mais prennent leur repas fans laver les mains?",
        6: "Il répondit, & leur dit, Certainement Efaïe a bien prophetizé de vous hypocrites: comme il eft efcrit, Ce peuple-ici m'honore des levres, mais leur coeur eft bien fort efloigné de moi.",
        7: "Mais ils m'honorent en vain, enfeignant des doctrines, qui ne font que des commandemens d'hommes.",
        8: "Car en laiffant le commandement de Dieu, vous retenez la tradition des hommes, affavoir les lavemens des brocs & des coupes: & faites beaucoup d'autres chofes femblables.",
        9: 'Il leur dit auffi, Vous annullez bien le commandement de Dieu, afin que vous gardiez voftre tradition.',
        10: "Car Moyfe a dit, Honore ton pere & ta mere. Item, Qui maudira fon pere ou fa mere, qu'il meure de mort.",
        11: "Mais vous dites, Si quelqu'un dit à fon pere ou à fa mere, Le corban (c'eft à dire le don) qui fera fait de par moi, viendra à ton profit, il fera hors de coulpe.",
        12: "Et ne fouffrez plus qu'il faffe rien au benefice de fon pere ou de fa mere.",
        13: 'Ainfi vous mettez la parole de Dieu à neant par voftre tradition que vous avez eftablie, & faites plufieurs chofes femblables.',
        14: 'Puis ayant appellé toutes les troupes, il leur dit, Efcoutez moi, vous tous, & entendez.',
        15: "Il n'y a rien de ce qui entre par dehors en l'homme, qui le puiffe foüiller: mais les chofes qui fortent de lui, ce font les chofes qui foüillent l'homme.",
        16: "Si quelqu'un a des oreilles pour ouïr, qu'il oye.",
        17: "Puis quand il fut entré en la maifon, s'eftant retiré d'avec les troupes, fes difciples l'interrogerent touchant la fimilitude.",
        18: "Et il leur dit, Et vous, eftes-vous ainfi auffi fans entendement? n'entendez-vous point encore, que tout ce qui entre en l'homme par dehors ne le peut foüiller?",
        19: "Car il n'entre point en fon coeur, mais au ventre, & fort au retrait, purgeant toute les viandes.",
        20: "Il leur difoit donc, ce qui fort de l'homme, c'eft ce qui foüille l'homme.",
        21: "Car du dedans, c'eft à dire, du coeur des hommes, fortent les mauvaifes penfées, les adulteres, les paillardifes, les meurtres,",
        22: "Les larcins, les mauvaifes pratiques pour avoir le bien d'autrui, les méchancetez, la fraude, l'infolence, le mauvais regard, le blafpheme, la fierté, la folie.",
        23: "Tous ces maux-là fortent du dedans, & foüillent l'homme.",
        24: "Puis s'eftant levé de là, il s'en alla aux confins de Tyr & de Sidon: & eftant entré en une maifon, il vouloit que perfonne ne le fçeuft; mais il ne pût eftre celé.",
        25: "Car une femme de laquelle une petite fille avoit un efprit immonde, dés qu 'elle eût ouï parler de lui, vint & fe jetta à fes pieds:",
        26: "(Or cette femme eftoit Grecque, Syropheniciene de nation) & le pria qu'il jettaft le diable hors de fa fille.",
        27: "Et Jefus lui dit, Souffre que les enfans foyent les premiers raffafiez: car il n'eft pas bon de prendre le pain des enfans, & le jetter aux petits chiens.",
        28: 'Mais elle refpondit, & lui dit, Il eft vrai, Seigneur: car les petits chiens mangent fous la table des miettes que les enfans laiffent tomber.',
        29: "Alors il lui dit, Pour cette parole va-t'en: le diable eft forti de ta fille.",
        30: "Et quand elle s'en fut allée en fa maifon, elle trouva que le diable eftoit forti, & fa fille couchée fur le lict.",
        31: 'Puis Jefus eftant parti derechef des quartiers de Tyr & de Sidon, vint à la mer de Galilée, par le milieu des quartiers de Decapolis.',
        32: "Alors on lui amena un fourd ayant le parler empefché: & on le pria qu'il lui impofaft les mains.",
        33: "Et l'ayant tiré à part de la multitude, il mit fes doigts és oreilles d'icelui: & ayant craché lui toucha la langue.",
        34: "Puis en regardant au ciel, il foûpira, & lui dit, Hephphatah, c'eft à dire, Ouvre-toi.",
        35: 'Et incontinent fes oreilles furent ouvertes, & le lien de fa langue fut deflié, & il parla aifément.',
        36: 'Et il leur commanda de ne le dire à perfonne. Mais plus il le defendoit, & plus ils le publioyent.',
        37: "Et ils s'eftonnoyent tant & plus, difans, Il a tout bien fait: il fait ouïr les fourds, & parler les muëts.",
    },
    8: {
        1: "En ces jours-là, comme il y avoit de fort grandes troupes, & qu'elles n'avoyent rien à manger, Jefus appella fes difciples, & leur dit,",
        2: "Je fuis émeu de compaffion envers les troupes: car il y a déja trois jours qu'ils ne bougent d'avec moi, & ils n'ont rien à manger.",
        3: "Et fi je les renvoye à jeun en leur maifon, ils defaudront en chemin: car quelques-uns d'entr'eux font venus de loin.",
        4: "Et fes difciples lui refpondirent, D'où les pourra-t'on raffafier ici de pains en ce defert?",
        5: 'Et il leur demanda, Combien avez-vous de pains? Ils lui dirent, Sept.',
        6: "Alors il commanda aux troupes de s'affeoir par terre: & prit les fept pains, & apres avoir rendu graces, il les rompit, & les bailla à fes difciples, pour les mettre devant les troupes: & ils les mirent devant elles.",
        7: "Ils avoyent auffi quelque peu de petits poiffons: & apres qu'il eût rendu graces, il commanda qu'ils les miffent auffi devant les troupes.",
        8: 'Ils en mangerent donc, & furent raffafiez: & emporterent du refte des pieces de pain, fept corbeilles.',
        9: '(Or ceux qui en avoyent mangé eftoyent environ quatre mille.) Et puis il leur donna congé.',
        10: 'Et monta incontinent en une naffelle avec fes difciples, & vint és quartiers de Dalmanutha.',
        11: "Et les Pharifiens s'en vinrent, & fe prirent à difputer avec lui, lui demandant quelque figne du ciel, en le tentant.",
        12: "Alors il dit en foûpirant profondement en fon efprit, Pourquoi cette generation demande-t'elle un figne? En verité je vous dis, qu'il ne fera point donné de figne à cette generation.",
        13: "Et les ayant laiffez, il monta derechef en la naffelle, & paffa à l'autre rivage.",
        14: "Or ils avoyent oublié à prendre des pains, & n'en avoyent qu'un avec eux en la naffelle.",
        15: "Et il leur commanda, difant, Avifez, donnez-vous garde du levain des Pharifiens, & du levain d'Herode.",
        16: "Dont ils penfoyent en eux-mefmes, difans, C'eft parce que nous n'avons point de pains.",
        17: "Et Jefus connoiffant cela, leur dit, Pourquoi penfez-vous touchant ce que vous n'avez point de pains? ne confiderez-vous point encore, &n'entendez-vous point? avez-vous encore voftre coeur ftupide?",
        18: "Ayans des yeux, ne voyez-vous point? ayans des oreilles, n'oyez-vous point? & n'avez-vous point de fouvenance?",
        19: 'Quand je diftribuai les cinq pains aux cinq mille hommes, combien en recüeilliftes-vous de corbeilles pleines du refte des pieces? Ils lui dirent, Douze.',
        20: 'Et quand je diftribuai les fept pains aux quatre mille hommes, combien recüeilliftes-vous de corbeilles pleines du refte des pieces? Ils lui dirent, Sept.',
        21: "Et il leur dit, Comment n'entendez-vous point?",
        22: "Puis il vint à Bethfaïda: & ils lui prefenterent un aveugle, & le prioyent qu'il le touchaft.",
        23: "Alors il prit la main de l'aveugle, & le mena hors de la bourgade; & ayant craché fur fes yeux, & lui ayant impofé les mains, il lui demanda s'il voyoit quelque chofe.",
        24: 'Et cet homme-là ayant levé la veuë, dit, Je vois marcher des hommes qui femblent des arbres.',
        25: "Puis apres il mit derechef les mains fur les yeux d'icelui, & lui fit lever la veuë: & il fut rétabli, & les voyoit tous de loin clairement.",
        26: "Puis il le renvoya en fa maifon, difant, N'entre point en la bourgade, & ne le di à perfonne de la bourgade.",
        27: 'Et Jefus & fes difciples eftans partis de là, vinrent aux bourgades de Cefarée, dite de Philippe: & fur le chemin il interrogea fes difciples, leur difant, Qui difent les hommes que je fuis?',
        28: "Ils répondirent, les uns, Jean Baptifte: & les autres, Elie: & les autres, l'un des Prophetes.",
        29: 'Alors il leur dit, Et vous, qui dites-vous que je fuis? Pierre répondant, lui dit, Tu es le Chrift.',
        30: "Et il leur defendit avec menaces, qu'ils ne diffent cela de lui à perfonne.",
        31: "Et il commença à les enfeigner, qu'il faloit que le Fils de l'homme fouffrift beaucoup, & qu'il fuft rejetté des Anciens, & des principaux Sacrificateurs, & des Scribes: & qu'il fuft mis à mort, & qu'il reffufcitaft trois jours apres.",
        32: 'Et tenoit ces propos tout ouvertement. Alors Pierre le prit, & fe mit à le tancer:',
        33: 'Mais lui fe retournant, & regardant fes difciples, tança Pierre, difant, Va arriere de moi, Satan: car tu ne comprens point les chofes qui font de Dieu, mais celles qui font des hommes.',
        34: "Puis ayant appellé les troupes avec fes difciples, il leur dit, Quiconque veut venir apres moi, qu'il renonce à foi-mefme, & qu'il charge fur foi fa croix, & qu'il me fuive.",
        35: "Car quiconque voudra fauver fon ame, il la perdra: mais quiconque perdra fon ame pour l'amour de moi & de l'Evangile, celui-là la fauvera.",
        36: "Car que profitera-t'il à l'homme s'il a gaigné tout le monde, & qu'il faffe perte de fon ame?",
        37: "Ou que donnera l'homme pour recompenfe de fon ame?",
        38: "Car quiconque aura eu honte de moi & de mes paroles parmi cette nation adultere & pechereffe, le Fils de l'homme aura auffi honte de lui, quand il fera venu en la gloire de fon Pere avec les faints Anges.",
    },
    9: {
        1: "Il leur difoit auffi, En verité je vous dis, qu'il y a quelques-uns qui font ici prefens, qui ne goufteront point la mort, jufques à ce qu'ils ayent veu le regne de Dieu eftre venu avec puiffance:",
        2: 'Et le fixiéme jour apres, Jefus prit avec foi Pierre, & Jaques, & Jean, & les mena feuls à part fur une haute montagne: & fut transfiguré devant eux.',
        3: "Et fes veftemens devinrent reluifans, & fort blancs, comme neige, tels qu'il n'y a foulon fur la terre qui les fceuft ainfi blanchir.",
        4: 'Puis Elie fut veu avec Moyfe: & ils parloyent avec Jefus.',
        5: 'Alors Pierre prenant la parole dit à Jefus, Maiftre, il eft bon que nous foyons ici: faifons y donc trois tabernacles, un pour toi, & un pour Moyfe, & un pour Elie.',
        6: "Or il ne fçavoit ce qu'il difoit: car ils eftoyent épouvantez.",
        7: 'Et une nuée vint qui les enombra: puis de la nuée vint une voix qui difoit, Celui-ci eft mon Fils bien-aimé: écoutez-le.',
        8: "Et auffi-toft ayant regardé à l'entour ils ne virent plus perfonne, finon Jefus feul avec eux.",
        9: "Et comme ils defcendoyent de la montagne, il leur commanda expreffement qu'ils ne racontaffent à perfonne ce qu'ils avoyent veu, finon apres que le Fils de l'homme feroit reffufcité des morts.",
        10: "Donc ils retinrent cette parole-là en eux-mefmes, s'entre-demandans ce que c'eftoit à dire cela, Reffufciter des morts.",
        11: "Puis apres ils l'interrogerent, difans, Pourquoi les Scribes difent-ils qu'il faut qu'Elie vienne premierement.",
        12: "Il répondit, & leur dit, De vrai, Elie eftant venu premierement, doit reftablir toutes chofes: & comme il eft écrit du Fils de l'homme, il faut qu'il fouffre beaucoup, & qu'il foit aneanti.",
        13: "Mais je vous dis, que mefmes Elie eft venu, & ils lui ont fait tout ce qu'ils ont voulu, comme il eft écrit de lui.",
        14: "Puis eftant revenu vers les difciples, il vid une grande troupe à l'entour d'eux, & des Scribes qui queftionnoyent avec eux.",
        15: "Et incontinent toute la troupe le voyant, fut faifie d'eftonnement, & accourans ils le faluërent.",
        16: 'Alors il interrogea les Scribes, difant, Dequoi eftes-vous en queftion avec eux?',
        17: "Et quelqu'un de la troupe répondit, & dit, Maiftre, je t'ai amené mon fils qui a un efprit muët,",
        18: "Qui le dérompt par tout où il le prend; & alors il écume & grince les dents, & devient fec: & j'ai requis tes difciples qu'ils le jettaffent hors, mais ils n'ont peu.",
        19: 'Alors Jefus lui répondant, dit, O nation incredule! jufques à quand finalement ferai-je avec vous? jufques à quand finalement vous fupporterai-je? Amenez-le moi.',
        20: "Ils l'amenerent donc jufques à lui, & quand il l'eut veu, incontinent l'efprit le dérompit, dont l'enfant tomba à terre, & fe tournoit ça & là en écumant.",
        21: "Alors il interrogea le pere d'icelui, difant, Combien y a-t'il de temps que ceci lui eft advenu? Lequel dit, Dés fon enfance.",
        22: "Et fouvent il l'a jetté, & au feu, & en l'eau, pour le faire perir: mais fi tu y peux quelque chofe, aide nous, eftant émeu de compaffion envers nous.",
        23: 'Alors Jefus lui dit, Si tu le peux croire, toutes chofes font poffibles au croyant.',
        24: "Et incontinent le pere de l'enfant s'écriant avec larmes, dit, Je crois, Seigneur: fubvien à mon incredulité.",
        25: "Et quand Jefus vid que le peuple y accouroit l'un fur l'autre il tança l'efprit immonde, lui difant, Efprit muët & fourd, je te commande, moi, Sors de lui, & n'y rentre jamais.",
        26: "Alors l'efprit fortit, en s'écriant, & le dérompant bien fort, dont l'enfant devint comme mort, tellement que plufieurs difoyent, Il eft mort.",
        27: "Mais Jefus l'ayant pris par la main, le dreffa, & il fe leva.",
        28: "Puis eftant entré en la maifon, fes difciples l'interrogerent à part, difans, Pourquoi ne l'avons-nous pû jetter dehors?",
        29: 'Et il leur refpon dit, Cette efpece de diables ne peut fortir autrement que par oraifon & par jeune.',
        30: "Puis eftant partis de là, ils cheminerent par la Galilée: & il ne voulut point qu'aucun le fçeuft.",
        31: "Car il enfeignoit fes difciples, & leur difoit, Le Fils de l'homme, s'en va eftre livré és mains des hommes, & ils le feront mourir: mais apres qu'il aura efté mis à mort, il reffufcitera au troifiéme jour.",
        32: "Mais ils n'entendoyent point ce difcours, & craignoyent de le lui demander.",
        33: 'Apres ces chofes il vint à Capernaum: & quand il fut en la maifon, il les interrogea, difant, Dequoi difputiez-vous entre vous par le chemin?',
        34: "Et ils fe teurent: car ils avoyent difputé les uns contre les autres en chemin, qui eftoit le plus grand d' entr'eux.",
        35: "Et quand il fut affis, il appella les douze, & leur dit, Si quelqu'un veut eftre le premier, il fera le dernier de tous, & le ferviteur de tous.",
        36: "Et ayant pris un petit enfant, il le mit au milieu d'eux: & apres l'avoir pris entre fes bras, il leur dit,",
        37: "Quiconque recevra l'un de tels petits enfans en mon Nom, il me reçoit: & quiconque me reçoit, il ne me reçoit pas, mais il reçoit celui qui m'a envoyé.",
        38: "Alors Jean prit la parole, & dit, Maiftre, nous avons veu quelqu'un qui jettoit hors les diables par ton Nom, lequel toutefois ne nous fuit point: & nous l'avons empefché, d'autant qu'il ne nous fuit point.",
        39: "Et Jefus dit, Ne l'empefchez point: car il n'y a perfonne qui faffe vertu par mon Nom, qui auffi-toft puiffe mal parler de moi.",
        40: "Car qui n'eft point contre nous, il eft pour nous.",
        41: "Car quiconque vous donnera un verre d'eau à boire en mon Nom, parce que vous eftes à Chrift, en verité je vous dis, qu'il ne perdra pas fon falaire.",
        42: "Et quiconque fcandalizera l'un de ces petits qui croyent en moi, il lui vaudroit mieux qu'on lui mift une pierre de meule à l'entour de fon col, & qu'on le jettaft en la mer.",
        43: "Que fi ta main te fait chopper, coupe-la: il vaut mieux que tu entres manchot en la vie, que d'avoir deux mains, & aller en la gehenne, au feu qui ne s'efteint point.",
        44: "Là où leur ver ne meurt point, & le feu ne s'efteint point.",
        45: "Et fi ton pied te fait chopper, coupe-le: il vaut mieux que tu entres boiteux en la vie, que d'avoir deux pieds, & eftre jetté en la gehenne, au feu qui ne s'efteint point:",
        46: "Là où leur ver ne meurt point, & le feu ne s'efteint point.",
        47: "Si auffi ton oeil te fait chopper, arrache-le: il vaut mieux que tu entres au royaume de Dieu, n'ayant qu'un oeil, que d'avoir deux yeux & eftre jetté en la gehenne du feu:",
        48: "Là où leur ver ne meurt point, & le feu ne s'efteint point.",
        49: 'Car un chacun fera falé de feu, & toute oblation fera falée de fel.',
        50: "C'eft une bonne chofe que le fel: mais fi le fel perd fa faveur, dequoi lui rendra-t'on fa faveur? Ayez du fel en vous-mefmes, & foyez en paix entre vous.",
    },
    10: {
        1: "Puis eftant parti de là, il vint és quartiers de Judée, outre le Jordain: & derechef les troupes s'affemblerent vers lui, & derechef il les enfeignoit, comme il avoit accouftumé.",
        2: "Alors les Pharifiens vinrent, & le tentans lui demanderent, Eft-il permis à l'homme de delaiffer fa femme?",
        3: "Il refpondit, & leur dit, Qu'eft-ce que Moyfe vous a commandé?",
        4: "Ils dirent, Moyfe a permis d'écrire la lettre de divorce, & de la delaiffer.",
        5: 'Et Jefus refpondant leur dit, Il vous a écrit ce commandement pour la dureté de voftre coeur.',
        6: 'Mais au commencement de la creation, Dieu les fit mafle & femelle.',
        7: "Pour cette caufe l'homme laiffera fon pere & fa mere, & s'adjoindra à fa femme:",
        8: 'Et les deux feront une mefme chair: partant ils ne font plus deux, mais une mefme chair.',
        9: "Donc ce que Dieu a conjoint, que l'homme ne le fepare point.",
        10: "Derechef fes difciples l'interrogerent de cela mefme en la maifon.",
        11: 'Et il leur dit, Quiconque delaiffera fa femme, & fe mariera à une autre,commet adultere contre elle.',
        12: 'Pareillement fi la femme delaiffe fon mari, & fe marie à un autre, elle commet adultere.',
        13: "Et ils lui prefenterent de petits enfans, afin qu'il les touchaft: mais les difciples tançoyent ceux qui les prefentoyent.",
        14: 'Et Jefus voyant cela, il en fut indigné, & leur dit, Laiffez les petits enfans venir à moi, & ne les en empefchez point: car à tels eft le royaume de Dieu.',
        15: "En verité je vous dis, Que quiconque ne recevra le royaume de Dieu comme petit enfant, n'entrera point en icelui.",
        16: 'Et apres les avoir pris entre fes bras, leur impofant les mains, il les benit.',
        17: "Et comme il fortit pour fe mettre en chemin, quelqu'un accourut, & s'eftant agenoüillé devant lui, l'interrogea, difant, Bon Maiftre, que ferai-je pour heriter la vie eternelle?",
        18: "Mais Jefus lui refpon dit, Pourquoi m'appelles-tu bon? il n'y a nul bon qu'un feul, affavoir Dieu.",
        19: 'Tu fçais les commandemens: Ne commets point adultere. Ne tuë point. Ne dérobe point. Ne di point faux témoignage. Ne fai dommage à perfonne. Honore ton pere & ta mere.',
        20: "Il refpondit, & lui dit, Maiftre, j'ai gardé toutes ces chofes-là dés ma jeuneffe.",
        21: "Et Jefus ayant jetté l'oeil fur lui, l'aima, & lui dit, Il te manque une chofe: va, & ven tout ce que tu as, & le donne aux pauvres, & tu auras un trefor au ciel, puis vien, & me fui, ayant chargé la croix.",
        22: "Mais il fut fafché de ce mot, & s'en alla tout trifte: car il avoit de grands biens.",
        23: "Alors Jefus ayant regardé à l'entour, dit à fes difciples, Combien ceux qui ont des richeffes, entreront-ils difficilement au royaume de Dieu!",
        24: "Et fes difciples s'eftonnerent de ce difcours. Mais Jefus prenant derechef la parole, leur dit, Enfans, qu'il eft difficile à ceux qui fe fient és richeffes, d'entrer au royaume de Dieu!",
        25: "Il eft plus aifé qu'un chameau paffe par le trou d'une aiguille, que non pas qu'un riche entre au royaume de Dieu.",
        26: "Dont ils s'eftonnerent d'autant plus, difans entr'eux, Et qui peut eftre fauvé?",
        27: 'Mais Jefus les ayant regardez, dit, Il eft impoffible quant aux hommes, mais non point quant à Dieu; car toutes chofes font poffibles à Dieu.',
        28: "Alors Pierre fe prit à lui dire, Voici, nous avons tout abandonné, & t'avons fuivi.",
        29: "Jefus refpondant dit, En verité je vous dis, qu'il n'y a nul qui ait laiffé maifon, ou freres, ou foeurs, ou pere, ou mere, ou femme, ou enfans, ou champs, pour l'amour de moi, & de l'Evangile,",
        30: "Qui n'en reçoive maintenant en ce temps-ici cent fois autant, maifons, & freres, & soeurs, & mere, & enfans, & champs, avec perfecutions: & au fiecle à venir, la vie eternelle.",
        31: 'Mais plufieurs qui font les premiers, feront les derniers: & les derniers feront les premiers.',
        32: "Or ils eftoyent en chemin, montans à Jerufalem: & Jefus alloit devant eux; & ils s'épouvantoyent, & craignoyent en le fuivant. Et ayant derechef pris les douze, il fe mit à leur declarer les chofes qui lui devoyent avenir,",
        33: "Difant, Voici, nous montons à Jerufalem: & le Fils de l'homme fera livré aux principaux Sacrificateurs, & aux Scribes: & ils le condamneront à mort, & le livreront aux nations:",
        34: 'Et fe mocqueront de lui, & le foüetteront, & cracheront contre lui, puis ils le feront mourir: mais il reffufcitera au troifiéme jour.',
        35: 'Alors Jaques & Jean, fils de Zebedée vinrent à lui, difans, Maiftre, nous voudrions que tu nous fiffes ce que nous te demanderons.',
        36: 'Et il leur dit, Que voulez-vous que je vous faffe?',
        37: "Et ils lui dirent, Octroye-nous que nous foyons affis en ta gloire, l'un à ta main droite & l'autre à ta gauche.",
        38: 'Et Jefus leur dit, Vous ne fçavez ce que vous demandez: pouvez-vous boire la coupe que je dois boire, & eftre baptizez du baptefme dont je dois eftre baptizé?',
        39: 'Et ils lui dirent, Nous le pouvons. Et Jefus leur dit, Il eft vrai que vous boirez la coupe que je dois boire, & que vous ferez baptizez du baptefme dont je dois eftre baptizé:',
        40: "Mais de feoir à ma droite & à ma gauche, ce n'eft point à moi de le donner: mais il fera donné à ceux aufquels il eft preparé.",
        41: "Ce que les dix autres ayant ouï, ils commencerent à s'indigner contre Jaques & Jean.",
        42: "Mais Jefus les appellant, leur dit, Vous fçavez que ceux qui font eftat de dominer fur les nations, les maiftrifent: & les grands d'entr'eux ufent d'authorité fur elles:",
        43: 'Mais il ne fera point ainfi entre vous: ains quiconque voudra eftre le plus grand entre vous, fera voftre miniftre.',
        44: "Et quiconque d'entre vous voudra eftre le premier, fera le ferviteur de tous.",
        45: "Car auffi le Fils de l'homme n'eft point venu pour eftre fervi: mais pour fervir, & donner fa vie en rançon pour plufieurs.",
        46: "Puis apres ils arriverent à Jerico: & lui partant de Jerico avec fes difciples, & une grande troupe, un aveugle, dit Bartimée, c'eft à dire, fils de Timée, eftoit affis auprés du chemin, & mendioit:",
        47: "Lequel ayant entendu que c'eftoit Jefus le Nazarien, fe prit à crier, & à dire, Jefus Fils de David, aye pitié de moi.",
        48: "Et plufieurs le tançoyent, afin qu'il fe teuft: mais il crioit tant plus fort, Fils de David, aye pitié de moi.",
        49: "Et Jefus s'eftant arrefté, dit qu'on l'appellaft: & ils appellerent l'aveugle, lui difans, Pren courage, leve-toi: il t'appelle.",
        50: "Et en jettant bas fon manteau, il fe leva, & s'en vint vers Jefus.",
        51: "Alors Jefus prenant la parole, lui dit, Que veux-tu que je te faffe? Et l'aveugle lui dit, Maiftre, que je recouvre la veuë.",
        52: "Et Jefus lui dit, Va-t'en, ta foi t'a fauvé. Et incontinent il recouvra la veuë, & fuivoit Jefus par le chemin.",
    },
    11: {
        1: 'Et comme ils approchoyent de Jerufalem, eftans prés de Bethphagé & de Bethanie, vers le mont des Oliviers, il envoya deux de fes difciples.',
        2: "Et il leur dit, Allez-vous-en en cette bourgade qui eft vis à vis de vous: & incontinent que vous y entrerez, vous trouverez un afnon attaché, fur lequel jamais homme ne s'affit: détachez-le, & l'amenez.",
        3: "Et fi quelqu'un vous dit, Pourquoi faites-vous cela? dites que le Seigneur en a affaire: & incontinent il l'envoyera ici.",
        4: "Ils partirent donc, & trouverent l'afnon qui eftoit attaché dehors aupres de la porte, entre deux chemins, & le détacherent.",
        5: 'Et quelques-uns de ceux qui eftoyent là, leur dirent, Que voulez-vous faire de détacher cet afnon?',
        6: 'Mais ils leur refpon dirent comme Jefus leur avoit commandé: & ils les laifferent aller.',
        7: "Ils amenerent donc l'afnon à Jefus, & mirent leurs veftemens fur icelui: & il s'affit deffus.",
        8: 'Et plufieurs eftendoyent leurs veftemens par le chemin: les autres coupoyent des rameaux des arbres, & les efpandoyent par le chemin.',
        9: 'Et ceux qui alloyent devant, & ceux qui fuivoyent, crioyent, difans, Hofanna: Benit foit celui qui vient au nom du Seigneur.',
        10: 'Benit foit le regne de David noftre pere, lequel vient au nom du Seigneur: Hofanna és lieux tres-hauts.',
        11: 'Ainfi Jefus entra dans Jerufalem, & au temple: & quand il eut regardé de toutes parts, & que déja il eftoit tard, il fortit pour aller à Bethanie avec les douze:',
        12: 'Et le lendemain quand ils furent partis de Bethanie, il eut faim:',
        13: "Et voyant de loin un figuier qui avoit des fueilles, il s'y en alla pour voir s'il y trouveroit quelque chofe: & y eftant venu, il ne trouva rien finon des fueilles: car ce n'eftoit pas la faifon des figues.",
        14: "Alors Jefus prenant la parole dit au figuier, Qu'à jamais perfonne ne mange du fruit de toi. Et fes difciples l'entendirent.",
        15: 'Ils vinrent donc à Jerufalem. Et quand Jefus fut entré au temple, il fe prit à jetter hors ceux qui vendoyent & achetoyent au temple, & renverfa les tables des changeurs, & les felles de ceux qui vendoyent des pigeons.',
        16: 'Et ne permettoit point que perfonne portaft aucun vaiffeau par le temple.',
        17: "Et enfeignoit, en leur difant, N'eft-il pas écrit, Ma Maifon fera appellée maifon d'oraifon par toutes nations? mais vous en avez fait une caverne de brigands.",
        18: "Ce que les Scribes & les principaux Sacrificateurs ayant entendu, ils cherchoyent comment ils le feroyent perir: car ils le craignoyent, à caufe que tout le commun peuple s'eftonnoit de fa doctrine.",
        19: 'Et le foir eftant venu, Jefus fortit de la ville.',
        20: 'Et le matin comme ils paffoyent aupres du figuier,ils le virent feché dés les racines.',
        21: "Alors Pierre s'eftant reffouvenu, lui dit, Maiftre, voici, le figuier que tu as maudit eft feché.",
        22: 'Et Jefus refpondant leur dit, Ayez la foi de Dieu.',
        23: "En verité je vous dis, que quiconque dira à cette montagne, Enleve-toi, & te jette en la mer: & ne fera point de difficulté en fon coeur, mais croira que ce qu'il dit fe fera, tout ce qu'il aura dit lui fera fait.",
        24: 'Partant je vous dis, Tout ce que vous demanderez en priant, croyez que vous le recevrez: & il vous fera fait.',
        25: "Mais quand vous vous prefenterez pour faire voftre oraifon, pardonnez fi vous avez quelque chofe contre quelqu'un, comme voftre Pere qui eft és cieux vous pardonne auffi vos fautes.",
        26: 'Car fi vous ne pardonnez, voftre Pere qui eft és cieux ne vous pardonnera point auffi vos fautes.',
        27: 'Puis derechef ils vinrent à Jerufalem: & comme il cheminoit au temple, les principaux Sacrificateurs, & les Scribes, & les Anciens vinrent vers lui:',
        28: "Et ils lui dirent, De quelle authorité fais-tu ces chofes? & qui eft celui qui t'a donné cette authorité que tu faffes ces chofes?",
        29: "Et Jefus refpondant leur dit, Je vous interrogerai auffi d'une chofe, & me refpondez: & alors je vous dirai de quelle authorité je fais ces chofes.",
        30: 'Le Baptefme de Jean eftoit-il du ciel ou des hommes? Refpondez-moi.',
        31: "Or ils difputoyent entr'eux, difans, Si nous difons, Du ciel, il dira, Pourquoi ne l'avez-vous point creu?",
        32: "D'autre-part, fi nous difons, Des hommes, nous craignons le commun peuple. Car tous tenoyent que Jean avoit efté vrayement Prophete.",
        33: 'Alors pour refponfe ils dirent à Jefus, Nous ne fçavons. Et Jefus refpondant leur dit, Je ne vous dirai point auffi de quelle authorité je fais ces chofes.',
    },
    12: {
        1: "Puis il fe prit à leur dire par fimilitude, Quelqu'un planta une vigne, & l'environna d'une haye, & y creufa une foffe pour un preffoir, & y baftit une tour: puis apres il la loüa à des vignerons, & s'en alla dehors.",
        2: "Or en la faifon il envoya un ferviteur vers les vignerons, afin de recevoir d'eux du fruit de la vigne.",
        3: 'Mais eux le prenans, le battirent & le renvoyerent à vuide.',
        4: "Derechef il leur envoya un autre ferviteur: & lui jettans des pierres ils lui froifferent toute la tefte, & le renvoyerent, l'ayant honteufement traitté.",
        5: 'Et derechef il en envoya encore un autre, lequel ils tuërent: & plufieurs autres, defquels ils battirent les uns, & tuërent les autres.',
        6: 'Or ayant encore un fils bien-aimé, il le leur envoya auffi pour le dernier, difant, Ils revereront mon fils.',
        7: "Mais ces vignerons-là dirent entr'eux, C'eft ici l'heritier: venez, tuons-le, & l'heritage fera noftre.",
        8: 'Et le prenans ils le tuërent, & le jetterent hors de la vigne.',
        9: "Que fera donc le feigneur de la vigne? Il viendra, & fera perir ces vignerons-là, & baillera la vigne à d'autres.",
        10: "Et n'avez-vous point leu cette Ecriture? La pierre que les edifians ont rejettée, eft devenuë la maiftreffe pierre du coin:",
        11: "Ceci a efté fait par le Seigneur, & c'eft une chofe merveilleufe devant nos yeux.",
        12: "Alors ils tafcherent de le faifir, mais ils craignirent le peuple: car ils connurent bien qu'il avoit dit cette fimilitude contr'eux: & en le laiffant, ils s'en allerent.",
        13: "Or ils envoyerent quelques-uns des Pharifiens & des Herodiens, pour l'enlacer en paroles:",
        14: "Lefquels eftans venus vers lui, lui dirent, Maiftre, nous fçavons que tu es veritable, & que tu ne te foucies d'aucun: car tu n'as point d'égard à l'apparence des hommes, mais tu enfeignes la voye de Dieu en verité: Eft-il permis de payer le tribut à Cefar, ou non? le payerons-nous, ou fi nous ne le payerons point?",
        15: 'Lui connoiffant leur hypocrifie, leur dit, Pourquoi me tentez-vous? apportez moi un denier, que je le voye.',
        16: 'Et ils le lui prefenterent. Alors il leur dit, De qui eft cette image, & cette infcription? Ils lui dirent, De Cefar.',
        17: 'Et Jefus refpondant leur dit, Rendez à Cefar les chofes qui font à Cefar, & à Dieu celles qui font à Dieu. Et ils en furent eftonnez.',
        18: "Alors les Sadduciens (qui difent qu'il n'y a point de refurrection) vinrent à lui, & l'interrogerent, difans,",
        19: "Maiftre, Moyfe nous a laiffé par efcrit, Que fi le frere de quelqu'un eft mort, & a laiffé fa femme, & n'a point laiffé d'enfans, que fon frere prenne la femme d'icelui, & qu'il fufcite lignée à fon frere.",
        20: 'Or il y avoit fept freres, dont le premier prit une femme, & mourant ne laiffa point de lignée.',
        21: 'Et le fecond la prit, & mourut: & lui auffi ne laiffa point de lignée. Et le troifiéme femblablement.',
        22: 'Les fept donc la prirent, ne laiffans point de lignée. La femme auffi mourut la derniere de tous.',
        23: "En la refurrection donc, quand ils feront reffufcitez, duquel d'eux fera-t'elle femme? car les fept l'ont euë à femme.",
        24: "Alors Jefus refpondant leur dit, Ce que vous vous fourvoyez, n'eft-ce pas dautant que vous ne fçavez point les Efcritures, ni la puiffance de Dieu?",
        25: 'Car quand ils feront reffufcitez des morts, ils ne prendront point à femme, & on ne leur baillera point de femmes en mariage: mais ils feront comme les Anges qui font és cieux.',
        26: "Et quant aux morts, pour montrer qu'ils reffufcitent, n'avez-vous point leu au livre de Moyfe, comme Dieu parla à lui au buiffon, difant, Je fuis le Dieu d'Abraham, & le Dieu d'Ifaac, & le Dieu de Jacob?",
        27: "Dieu n'eft point le Dieu des morts, mais le Dieu des vivans. Vous vous fourvoyez donc grandement.",
        28: "Alors quelqu'un des Scribes eftant venu là, les ayant ouïs difputer enfemble, & fçachant qu'il leur avoit refpondu bien à propos, l'interrogea, difant, Quel eft le premier commandement de tous?",
        29: 'Jefus lui refpondit, Le premier de tous les commandemens eft, Efcoute Ifraël, Le Seigneur noftre Dieu eft le feul Seigneur.',
        30: 'Et tu aimeras le Seigneur ton Dieu de tout ton coeur, & de toute ton ame, & de toute ta penfée, & de toute ta force. Celui-ci eft le premier commandement.',
        31: "Et le fecond femblable à icelui, eft, Tu aimeras ton prochain comme toi-mefme. Il n'y a point d'autre commandement plus grand que ceux-ci.",
        32: "Et le Scribe lui dit, Maiftre, tu as bien dit à la verité, qu'il y a un feul Dieu, & qu'il n'y en a point d'autre que lui:",
        33: "Et que l'aimer de tout fon coeur, & de toute fon intelligence, & de toute fon ame, & de toute fa force, & aimer fon prochain comme foi-mefme, eft plus que tous les holocauftes & les facrifices.",
        34: "Et Jefus voyant qu'il avoit refpondu prudemment, lui dit, Tu n'es pas loin du royaume de Dieu. Et nul ne l'ofoit plus interroger.",
        35: 'Et Jefus enfeignant au temple, prenant la parole, leur dit, Comment eft-ce que les Scribes difent que le Chrift eft fils de David?',
        36: "Car David mefme a dit par le faint Efprit, le Seigneur a dit à mon Seigneur, Sieds-toi à ma dextre, jufques à ce que j'aye mis tes ennemis pour le marchepied de tes pieds.",
        37: "David donc lui-mefme l'appelle Seigneur; comment donc eft-il fon fils? Et de grandes troupes prenoyent plaifir à l'ouïr.",
        38: 'Davantage, il leur difoit en fa doctrine, Donnez-vous garde des Scribes, qui aiment à fe promener en robbes longues, & les falutations és marchez:',
        39: 'Et les premieres feances és Synagogues, & les premieres places és banquets:',
        40: 'Qui mangent entierement les maifons des veuves: voire un faifant femblant de prier beaucoup; ils en recevront plus grande condamnation.',
        41: "Jefus auffi eftant affis vis à vis du tronc, prenoit garde comment le peuple mettoit de l'argent au tronc.",
        42: 'Or plufieurs riches y mettoyent beaucoup: & une pauvre veuve vint, laquelle y mit deux petites pieces qui font un quadrin.',
        43: 'Alors appellant fes difciples, il leur dit, En verité je vous dis, que cette pauvre veuve a plus mis au tronc que tous ceux qui y ont mis.',
        44: "Car tous y ont mis de ce qui leur abonde: mais celle-ci y a mis de fa pauvreté tout ce qu'elle avoit, voire toute fa fubftance.",
    },
    13: {
        1: 'Et comme il partoit du temple, un de fes difciples lui dit, Maiftre, regarde quelles pierres, & quels baftimens.',
        2: 'Alors Jefus refpondant lui dit, Ne vois-tu pas ces grands baftimens? Il ne fera laiffé pierre fur pierre qui ne foit demolie,',
        3: "Et comme il étoit affis au mont des Oliviers vis à vis du temple, Pierre & Jaques, Jean & André l'interrogerent à part,",
        4: 'Difans, Di nous quand ces chofes-là adviendront, & quel fera le figne quand toutes ces chofes doivent eftre accomplies.',
        5: "Alors Jefus leur refpondant, commença à leur dire, Prenez garde que quelqu'un ne vous feduife.",
        6: "Car plufieurs viendront en mon Nom, difans, C'eft moi qui fuis le Chrift, & en feduiront plufieurs.",
        7: 'Or quand vous orrez des guerres & des bruits de guerres, ne foyez point troublez: car il faut que ces chofes adviennent, mais ce ne fera pas encore la fin.',
        8: "Car nation s'élevera contre nation, & royaume contre royaume: & il y aura des tremblemens de terre en tous lieux, & des famines & des troubles: ces chofes-là feront des commencemens de douleurs.",
        9: 'Mais prenez garde à vous-mefmes: car ils vous livreront aux confiftoires, & aux Synagogues: vous ferez foüettez, & ferez prefentez devant les gouverneurs & les rois, à caufe de moi, pour leur eftre en tefmoignage.',
        10: "Et il faut que l'Evangile foit premierement prefché en toutes les nations.",
        11: "Or quand ils vous meneront pour vous livrer, ne foyez point auparavant en fouci de ce que vous aurez à dire, & n'y meditez point: mais tout ce qui vous fera donné en cet inftant-là, dites-le: car ce n'eft pas vous qui parlez, mais le S. Efprit.",
        12: "Alors le frere livrera fon frere à la mort, & le pere l'enfant: & les enfans s'éleveront contre leurs peres & leurs meres, & les feront mettre à mort.",
        13: 'Et vous ferez haïs de tous à caufe de mon Nom: mais qui perfeverera jufques à la fin, celui-là fera fauvé.',
        14: "Or quand vous verrez l'abomination de la defolation (qui a efté dite par Daniel le Prophete) eftre eftablie là où elle ne doit point eftre: (qui lit l'entende) alors que ceux qui feront en Judée s'enfuyent aux montagnes.",
        15: "Et que celui qui fera fur la maifon, ne defcende point en la maifon, & n'y entre point pour emporter aucune chofe de fa maifon.",
        16: 'Et que celui qui fera au champ, ne retourne point en arriere, pour emporter fon habillement.',
        17: 'Mais mal-heur fur celles qui feront enceintes, & fur celles qui allaitteront en ces jours-là.',
        18: "Priez donc que voftre fuite n'advienne point en hyver.",
        19: "Car en ces jours-là il y aura une telle affliction, qu'il n'y en a point eu de femblable depuis le commencement de la creation des chofes que Dieu a creées, jufques à maintenant, & n'y en aura.",
        20: "Et fi le Seigneur n'euft abbregé ces jours-là, nulle perfonne ne feroit fauvée: mais il a abbregé ces jours-là, à caufe des éleus qu'il a éleus.",
        21: "Et alors fi quelqu'un vous dit, Voici, le Chrift eft ici: ou, Voici, il eft là, ne le croyez point.",
        22: "Car de faux Chrifts & de faux Prophetes s'éleveront, & feront des fignes & des miracles, pour feduire mefmes les éleus, s'il eftoit poffible.",
        23: 'Mais donnez-vous en garde: voici, je vous ai predit le tout.',
        24: 'Auffi en ces jours-là, apres cette affliction-là, le Soleil fera obfcurci, & la Lune ne donnera point de clarté.',
        25: 'Et les étoiles du ciel cherront, & les vertus qui font és cieux feront efbranlées.',
        26: "Et alors ils verront le Fils de l'homme venir és nuées avec grande puiffance & gloire.",
        27: 'Alors il envoyera fes Anges, & affemblera en un fes éleus, des quatre vents, depuis le bout de la terre jufques au bout du ciel.',
        28: "Or apprenez la fimilitude du figuier: Quand fon rameau eft en féve, & qu'il jette des fueilles, vous connoiffez que l'efté eft prochain.",
        29: "Vous auffi pareillement, quand vous verrez que ces chofes-là adviendront, fçachez qu'il eft prochain à la porte.",
        30: 'En verité je vous dis, que cette generation ne paffera point, tant que toutes ces chofes-là foyent faites.',
        31: 'Le ciel & la terre pafferont, mais mes paroles ne pafferont point.',
        32: "Or quant à ce jour-là & à l'heure, nul ne le fçait, non pas mefmes les Anges qui font au Ciel, ni auffi le Fils: mais le Pere.",
        33: 'Prenez garde à vous veillez, & priez: car vous ne fçavez quand fera ce temps-là.',
        34: "C'eft comme fi un homme allant dehors, laiffoit fa maifon, & donnoit authorité à fes ferviteurs, & à un chacun fa tafche, & commandoit au portier qu'il veillaft.",
        35: "Veillez donc: (car vous ne fçavez quand le Seigneur de la maifon viendra, au foir, ou à minuit, ou à l'heure que le coq chante, ou au matin.)",
        36: "De peur qu'arrivant foudainement, il vous trouve dormans.",
        37: 'Or les chofes que je vous dis, je les dis à tous: Veillez.',
    },
    14: {
        1: 'Or la fefte de Pafque, & des pains fans levain, eftoit deux jours apres: & les principaux Sacrificateurs & les Scribes cherchoyent comment ils le pourroyent faifir par fineffe: & le mettre à mort.',
        2: "Mais ils difoyent, Non point durant la fefte, de peur qu'il fe face tumulte entre le peuple.",
        3: "Et comme il eftoit à Bethanie en la maifon de Simon, dit le lepreux, & qu'il eftoit à table, il vint là une femme qui avoit une boite d'onguent d'afpic liquide precieux: & elle rompit la boite, & efpandit l'onguent fur la tefte d'icelui.",
        4: 'Dont quelques-uns furent indignez en eux-mefmes, & difoyent, A quoi fert le dégaft de cet onguent?',
        5: "Car cet onguent pouvoit eftre vendu plus de trois cent deniers, & eftre donné aux pauvres. Ainfi ils en fremiffoyent contr'elle.",
        6: 'Mais Jefus dit, Laiffez-la, pourquoi lui donnez-vous de la fafcherie? elle a fait un bon acte envers moi.',
        7: "Parce que vous aurez toûjours les pauvres avec vous, & vous leur pourrez bien faire, toutes les fois que vous voudrez: mais vous ne m'aurez point toûjours.",
        8: "Elle a fait ce qui eftoit en elle: elle a anticipé d'oindre mon corps pour l'appareil de ma fepulture.",
        9: "En verité je vous dis, qu'en quelque lieu que cet Evangile fera prefché en tout le monde, cela auffi qu'elle a fait fera recité en memoire d'elle.",
        10: "Alors Judas Ifcariot, l'un des douze, s'en alla vers les principaux Sacrificateurs, afin qu'il le leur livraft.",
        11: "Lefquels l'ayant ouï s'éjouïrent, & lui promirent de lui donner de l'argent: & il cherchoit comment il le livreroit commodément.",
        12: "Or le premier jour des pains fans levain qu'on facrifioit l'agneau de Pafque, fes difciples lui dirent, Où veux-tu que nous allions, afin de t'apprefter à manger l'agneau de Pafque?",
        13: "Alors il envoya deux de fes difciples, & leur dit, Allez en la ville, & un homme vous viendra à la rencontre, portant une cruche d'eau: fuivez-le.",
        14: "Et en quelque lieu qu'il entrera, dites au maiftre de la maifon: Le maiftre dit, Où eft le logis où je mangerai l'agneau de Pafque avec mes difciples?",
        15: "Et il vous montrera une grande chambre ornée & preparée: appreftez-nous là l'agneau de Pafque.",
        16: "Ainfi les difciples partirent, & vinrent en la ville, & trouverent comme il leur avoit dit, & apprefterent l'agneau de Pafque.",
        17: "Puis le foir eftant venu, il s'en vint avec les douze.",
        18: "Et comme ils eftoyent à table, & mangeoyent, Jefus dit, En verité je vous dis, que l'un de vous qui mange avec moi me trahira.",
        19: "Alors ils fe prirent à fe contrifter: & lui dirent l'un apres l'autre, Eft-ce moi? & l'autre, Eft-ce moi?",
        20: "Mais il refpondit, & leur dit, C'eft l'un des douze, lequel trempe avec moi au plat.",
        21: "Certes le Fils de l'homme s'en va, felon qu'il eft écrit de lui: mais mal-heur à cet homme-là par lequel le Fils de l'homme eft trahi: il euft efté bon à cet homme-là de n'eftre point né.",
        22: 'Et comme ils mangeoyent, Jefus prit le pain: & apres avoir rendu graces, il le rompit: puis le leur bailla, & dit, Prenez, mangez, ceci eft mon corps.',
        23: 'Puis ayant pris la coupe, il rendit graces, & la leur bailla: & ils en burent tous.',
        24: 'Et il leur dit, Ceci eft mon fang, le fang du nouveau Teftament, lequel eft refpandu pour plufieurs.',
        25: 'En verité je vous dis, que je ne boirai plus du fruit de la vigne, jufques à ce jour-là que je le boirai nouveau au royaume de Dieu.',
        26: "Et quand ils eurent chanté le cantique, ils s'en allerent en la montagne des Oliviers.",
        27: 'Alors Jefus leur dit, Vous ferez tous fcandalifez en moi cette nuit-ici: car il eft écrit, Je fraperai le berger, & les brebis feront éparfes.',
        28: "Mais apres que je ferai reffufcité, j'irai devant vous en Galilée.",
        29: 'Et Pierre lui dit, Quand bien tous feroyent fcandalizez, fi eft-ce que je ne le ferai point.',
        30: "Alors Jefus lui dit, En verité je te dis, qu'aujourd'hui en cette propre nuit, devant que le coq ait chanté deux fois tu me renieras par trois fois.",
        31: 'Mais il difoit encore de plus fort, Quand mefmes il me faudroit mourir avec toi, fi eft-ce que je ne te renierai point. Et tous auffi difoyent de mefme.',
        32: "Puis apres ils vinrent en un lieu nommé Gethfemané: & il dit à fes difciples, Sées-vous ici, jufques à ce que j'aye prié.",
        33: "Alors il prit avec foi Pierre, & Jaques, & Jean, & commença à s'épouvanter, & à eftre fort angoiffé.",
        34: 'Alors il leur dit, Mon ame eft faifie de trifteffe jufques à la mort: demeurez ici, & veillez.',
        35: "Et s'en allant un peu plus outre, il fe jetta en terre: & prioit, Que s'il fe pouvoit faire, l'heure fe paffaft arriere de lui.",
        36: 'Et il difoit, Abba, Pere, toutes chofes te font poffibles, tranfporte cette coupe arriere de moi: toutesfois non point ce que je veux, mais ce que tu veux.',
        37: "Puis il vint, & les trouva dormans: & il dit à Pierre, Simon, dors-tu? n'as-tu peu veiller une heure?",
        38: "Veillez, & priez, que vous n'entriez en tentation: car quant à l'efprit il eft prompt, mais la chair eft foible.",
        39: "Et derechef il s'en alla, & pria, difant le mefme propos.",
        40: 'Puis eftant retourné, il les trouva derechef dormans, car leurs yeux eftoyent appefantis: & ils ne fçavoyent que lui refpondre.',
        41: "Puis il vint pour la troifiéme fois, & leur dit, Dormez dorefnavant, & vous repofez: il fuffit, l'heure eft venuë: voici, le Fils de l'homme s'en va eftre livré és mains des méchans.",
        42: "Levez-vous, allons: voici, celui qui me trahit s'approche.",
        43: "Et auffi-toft, comme il parloit encore, Judas (qui eftoit l'un des douze) vint & une grande troupe avec lui, avec des efpées & des baftons, de par les principaux Sacrificateurs, & les Scribes, & les Anciens.",
        44: "Or celui qui le trahiffoit avoit donné un fignal entr'eux, difant, Quiconque je baiferai, c'eft celui-là, faififfez-le & l'emmenez feurement.",
        45: "Quand donc il fut venu, incontinent il s'approcha de lui, & dit, Maiftre, Maiftre: & le baifa.",
        46: 'Alors ils jetterent les mains fur lui, & le faifirent.',
        47: "Et quelqu'un de ceux qui eftoyent là prefens tira fon efpée, & en frapa le ferviteur du fouverain Sacrificateur, & lui emporta l'oreille.",
        48: 'Alors Jefus prit la parole, & leur dit, Eftes-vous fortis comme apres un brigand avec des efpées & des baftons, pour me prendre?',
        49: "J'eftois tous les jours entre vous, enfeignant au temple, & vous ne m'avez point faifi: mais tout ceci eft advenu afin que les Efcritures foyent accomplies.",
        50: "Alors tous l'ayans abandonné, s'enfuïrent.",
        51: "Et un certain jeune homme le fuivoit, enveloppé d'un linceul fur le corps nud: & quelques jeunes gens le faifirent.",
        52: "Mais en laiffant fon linceul, il s'enfuït arriere d'eux tout nud.",
        53: "Or de là ils emmenerent Jefus au fouverain Sacrificateur, chez lequel s'affemblerent tous les principaux Sacrificateurs, les Anciens, & les Scribes.",
        54: 'Et Pierre le fuivoit de loin jufques dedans, en la court du fouverain Sacrificateur: & il eftoit affis avec les ferviteurs, & fe chauffoit au feu.',
        55: "Or les principaux Sacrificateurs & tout le confiftoire cherchoyent un tefmoignage contre Jefus, pour le mettre à mort: & n'en trouvoyent point.",
        56: "Car plufieurs difoyent de faux témoignages contre lui, mais les tefmoignages n'eftoyent point conformes.",
        57: "Alors quelques-uns s'éleverent, & porterent faux tefmoignage contre lui, difans,",
        58: "Nous l'avons ouï qu'il difoit, Je déferai ce temple-ici qui eft fait de main, & en trois jours j'en rebaftirai un autre qui ne fera point fait de main.",
        59: "Mais encore avec tout cela leurs tefmoignages n'eftoyent point conformes.",
        60: "Alors le fouverain Sacrificateur fe levant au milieu, interrogea Jefus, difant, Ne refpons-tu rien? qu'eft-ce que tefmoignent ceux-ci contre toi?",
        61: "Mais il fe teut, & ne refpondit rien. Derechef le fouverain Sacrificateur l'interrogea, & lui dit, Es-tu le Chrift le Fils de Dieu benit?",
        62: "Et Jefus lui dit, Je le fuis: & vous verrez le Fils de l'homme affis à la dextre de la vertu de Dieu, & venant és nuées du ciel.",
        63: "Alors le fouverain Sacrificateur defchira fes veftemens, & dit, Qu'avons-nous encore à faire de tefmoins?",
        64: 'Vous avez ouï le blafpheme: que vous en femble? Alors eux tous le condamnerent comme eftant coupable de mort.',
        65: 'Et quelques-uns fe prirent à cracher contre lui, & à lui couvrir la face, & à lui bailler des foufflets: & lui difoyent, Prophetize nous. Et les fergens lui bailloyent des coups de leurs verges.',
        66: 'Or comme Pierre eftoit en bas en la court, une des fervantes du fouverain Sacrificateur vint:',
        67: 'Et quand elle eut apperceu Pierre qui fe chauffoit, elle le regarda en face, & lui dit, Et toi, tu eftois avec Jefus le Nazarien.',
        68: 'Mais il le nia, difant, Je ne le connois point, & ne fçai ce que tu dis: & il fortit dehors au portail, & le coq chanta.',
        69: "Et quand la fervante l'eut veu derechef, elle fe prit à dire à ceux qui eftoyent là prefens, Celui-ci eft de ceux-là.",
        70: "Mais il le nia derechef. Et derechef un peu apres, ceux qui eftoyent là prefens, dirent à Pierre, Vrayement tu es de ceux-là, car tu es Galiléen, & ton langage s'y rapporte.",
        71: 'Alors il fe prit à fe maudire, & à jurer, difant, Je ne connois point cet homme-là que vous dites.',
        72: "Et le coq chanta pour la feconde fois, & Pierre fe reffouvint de la parole que Jefus lui avoit dite, Devant que le coq ait chanté deux fois, tu me renieras par trois fois. Et s'eftant jetté hors il pleura.",
    },
    15: {
        1: "Et incontinent au matin, les principaux Sacrificateurs avec les Anciens & les Scribes, & tout le confiftoire, ayans tenu confeil, lierent Jefus, & l'emmenerent, & le livrerent à Pilate.",
        2: "Et Pilate l'interrogea, difant, Es-tu le roi des Juifs? Jefus refpondant lui dit, Tu le dis.",
        3: "Et les principaux Sacrificateurs l'accufoyent de plufieurs chofes: mais lui ne refpondoit rien.",
        4: "Pilate donc l'interrogea derechef, difant, Ne refpons-tu rien? voila combien de chofes ils tefmoignent contre toi.",
        5: "Mais Jefus ne refpondit rien non plus, tellement que Pilate s' en eftonnoit.",
        6: "Or il leur relafchoit à la fefte un prifonnier, qui que ce fuft qu'ils demandaffent.",
        7: 'Et il y en avoit un, dit Barrabas, qui eftoit prifonnier avec fes complices de fedition, lefquels avoyent commis meurtre en la fedition.',
        8: "Et le peuple s'écriant tout haut, fe prit à demander qu'il fift comme il leur avoit toûjours fait.",
        9: 'Pilate donc leur refpondit, difant, Voulez-vous que je vous relafche le Roi des Juifs?',
        10: "Car il fçavoit bien que les principaux Sacrificateurs l'avoyent livré par envie.",
        11: "Mais les principaux Sacrificateurs émeurent le peuple, afin qu'il leur relafchaft pluftoft Barrabas.",
        12: 'Et Pilate refpondant leur dit derechef, Que voulez-vous donc que je face à celui que vous appellez Roi des Juifs?',
        13: "Et derechef ils s'écrierent, difant, Crucifie-le.",
        14: "Alors Pilate leur dit, Mais quel mal a-t'il fait? Et ils s'écrierent tant plus fort, Crucifie-le.",
        15: "Pilate donc voulant contenter le peuple, leur relafcha Barrabas, & apres avoir fait foüetter Jefus, le livra, afin qu'il fuft crucifié.",
        16: "Alors les foldats l'emmenerent dans la court qui eft le pretoire, & appellerent toute la bande.",
        17: "Et le veftirent d'une robbe de pourpre, & lui mirent à l'entour de la tefte une couronne d'épines qu'ils avoyent pliée.",
        18: 'Et fe prirent à le faluër, en difant, Bien te foit, Roi des Juifs.',
        19: 'Et ils lui frapoyent la tefte avec un rofeau, & crachoyent contre lui, & fe mettans à genoux, lui faifoyent la reverence.',
        20: "Puis apres quand ils fe furent moquez de lui, ils le deveftirent de la robbe de pourpre, & le reveftirent de fes veftemens, & l'emmenerent dehors pour le crucifier.",
        21: "Et contraignirent un certain paffant nommé Simon Cyrenien, lequel venoit des champs, qui eftoit pere d'Alexandre & de Rufus, de porter la croix d'icelui.",
        22: 'Et puis le menerent en la place de Golgotha, qui vaut autant à dire que la place du Teft.',
        23: 'Puis ils lui donnerent à boire du vin mixtionné avec de la myrrhe: mais il ne le prit point.',
        24: "Et quand ils l'eurent crucifié, ils partagerent fes veftemens, en jettant le fort fur iceux, pour fçavoir ce que chacun emporteroit.",
        25: 'Or il eftoit trois heures quand ils le crucifierent.',
        26: 'Et le dicton de fa condamnation portoit en écrit, LE ROI DES JUIFS.',
        27: "Ils crucifierent auffi avec lui deux brigands: l'un à fa droite, & l'autre à fa gauche.",
        28: "Ainfi fut accomplie l'Efcriture qui dit, Et il a efté mis au rang des malfaiteurs.",
        29: 'Et ceux qui paffoyent prés de là lui difoyent des outrages, hochans la tefte, & difans, Hé! toi, qui defais le temple & le rebaftis en trois jours,',
        30: 'Sauve-toi toi-mefme, & defcen de la croix.',
        31: 'Semblablement auffi les principaux Sacrificateurs mefmes fe moquans avec les Scribes difoyent les uns aux autres, Il a fauvé les autres, il ne fe peut fauver foi-mefme.',
        32: "Que le Chrift, le Roi d'Ifraël, defcende maintenant de la croix, afin que nous le voyïons, & le croyïons. Et ceux auffi qui eftoyent crucifiez avec lui, lui difoyent des outrages.",
        33: 'Mais quand il fut fix heures, il fe fit des tenebres fur tout le païs jufques à neuf heures.',
        34: "Et à neuf heures Jefus cria à haute voix, difant, Eloi, Eloi, lamma fabachthani? qui vaut autant à dire que Mon Dieu, Mon Dieu, pourquoi m'as-tu abandonné?",
        35: 'Et quelques-uns de ceux qui eftoyent là prefens, ayans ouï cela, difoyent, Voici, il appelle Elie.',
        36: "Et quelqu'un accourut, & emplit une efponge de vinaigre: & la mit à l'entour d'un rofeau, & lui en bailla à boire, difant, Laiffez, voyons fi Elie viendra pour l'ofter.",
        37: "Et Jefus apres avoir jetté un grand cri, rendit l'efprit.",
        38: 'Et le voile du temple fe fendit en deux, depuis le haut jufques au bas.',
        39: "Et le Centenier qui eftoit là vis à vis de lui, voyant qu'il avoit rendu l'efprit, en criant ainfi, dit, Veritablement cet homme eftoit le Fils de Dieu.",
        40: 'Il y avoit auffi des femmes qui regardoyent de loin: entre lefquelles eftoyent Marie Magdeleine, & Marie mere de Jaques le petit, & de Jofes, & Salomé.',
        41: "Lefquelles dés lors mefmes qu'il eftoit en Galilée, l'avoyent fuivi, & lui avoyent fubvenu: & plufieurs autres qui eftoyent montées enfemble avec lui à Jerufalem.",
        42: "Et le foir eftant déja venu, (dautant que c'eftoit le jour de la preparation, qui eft devant le Sabbat.)",
        43: "Jofeph d'Arimathée, confeiller honorable (lequel auffi attendoit le regne de Dieu) s'eftant enhardi, s'en vint vers Pilate, & lui demanda le corps de Jefus.",
        44: "Et Pilate s'eftonna de ce qu'il eftoit déja mort: puis ayant appellé le Centenier, il l'interrogea s'il y avoit long-temps qu'il eftoit mort.",
        45: "Ce qu'ayant connu du Centenier, il donna le corps à Jofeph.",
        46: "Et icelui ayant acheté un linceul, le defcendit de la croix, & l'enveloppa du linceul, & le mit dans un fepulcre qui eftoit taillé en un roc: puis il roula une pierre à la porte du fepulcre.",
        47: 'Et Marie Magdeleine, & Marie mere de Jofes, regardoyent où on le mettoit.',
    },
    16: {
        1: 'Or le Sabbat eftant paffé, Marie Magdeleine, & Marie mere de Jaques, & Salomé, acheterent des onguents aromatiques pour le venir embaumer.',
        2: 'Et de fort grand matin, le premier jour de la femaine, elles arriverent au fepulcre, le Soleil eftant levé.',
        3: "Et difoyent entr'elles, Qui nous roulera la pierre de la porte du fepulcre?",
        4: 'Et ayant regardé, elles virent que la pierre eftoit roulée, car elle eftoit fort grande.',
        5: "Puis eftant entrées dans le fepulcre, elles virent un jeune homme affis à main droite, veftu d'une robbe blanche: dont elles s'épouvanterent.",
        6: "Mais il leur dit, Ne vous efpouvantez point: vous cherchez Jefus le Nazarien qui a efté crucifié: il eft reffufcité, il n'eft point ici: voici le lieu où on l'avoit mis.",
        7: "Mais allez, dites à fes difciples, & à Pierre, qu'il s'en va devant vous en Galilée: vous le verrez là, comme il vous a dit.",
        8: "Et incontinent en partant de là elles s'enfuïrent arriere du fepulcre: car le tremblement & la frayeur les avoit faifies & n'en dirent rien à perfonne: car elles avoyent peur.",
        9: 'Or Jefus eftant reffufcité, le matin au premier jour de la femaine, apparut premierement à Marie Magdeleine, de laquelle il avoit jetté hors fept diables.',
        10: "Et elle s'en alla, & l'annonça à ceux qui avoyent efté avec lui: lefquels eftoyent en deüil & pleuroyent.",
        11: "Eux ayans entendu qu'il vivoit, & qu'elle l'avoit veu, ne le creurent point.",
        12: "Puis apres ces chofes, il fe montra en une autre forme à deux d'entr'eux, qui eftoyent en chemin pour aller aux champs:",
        13: "Et ceux-là eftans retournez l'annoncerent aux autres, mais ils ne les creurent non plus.",
        14: "Finalement il fe montra aux onze, eftans enfemble, affis, & leur reprocha leur incredulité & dureté de coeur, dautant qu'ils n'avoyent point creu ceux qui l'avoyent veu reffufcité.",
        15: "Et il leur dit, Allez-vous-en par tout le monde, & prefchez l'Evangile à toute creature.",
        16: "Qui aura creu & aura efté baptizé fera fauvé: mais qui n'aura point creu fera condamné.",
        17: 'Et ce font ici les fignes qui accompagneront ceux qui auront creu: Ils jetteront hors les diables par mon Nom: ils parleront de nouveaux langages:',
        18: 'Ils chafferont les ferpens. Et quand ils auront beu quelque chofe mortelle, elle ne leur nuira nullement: ils impoferont les mains fur les malades, & ils fe porteront bien.',
        19: "Or le Seigneur, apres avoir parlé à eux, fut élevé en haut au ciel: & s'affit à la dextre de Dieu.",
        20: "Eux auffi eftans partis prefcherent par tout, le Seigneur operant avec eux, & confirmant la parole par les fignes qui s'en enfuivoyent.",
    },
}
